/* L1s with no logical architecture element — a real gap in master 01 */
const UNALLOCATED = new Set(
  L1S.filter((r) => !ADJ[r].some((a) => NODE[a.id].type === "ArchitectureElement"))
);

const CW = 300, NW = 208, NH = 62, VGAP = 30;
const STEP = NH + VGAP;

/* Every node type maps to one clean integer lane along the V.
   Types that sit at the same stage (architecture / analysis, or
   the software-detail stage) share a lane and stack vertically,
   so nothing lands a few pixels off from its neighbour. */
const LANE = {
  StakeholderRequirement: 0,
  UseCase: 2,
  ArchitectureElement: 4, FMEAItem: 4, FunctionalSafetyArtifact: 4, CybersecurityArtifact: 4,
  ECUOrComputeNode: 5, ECUServiceNode: 5, ECUSmartNode: 5, Interface: 5, SoftwareRequirement: 5,
  SignalOrService: 6, SoftwareComponent: 6, DetailedDesign: 6,
  TestCase: 7, SupplierPackage: 7,
  ValidationEvidence: 8,
};
const laneOf = (n) =>
  n.type === "Requirement" ? (/L0/.test(n.subtype || "") ? 1 : 3) : (LANE[n.type] ?? 5);

/* ===== SECTION: Graph layout ===== */
/* ==========================================================================
   GRAPH LAYOUT — position the focused node and its expanded neighborhood into
   vertical lanes (by node type/rank) with fixed row spacing. Returns {pos,
   visible, edges} consumed by the Graph (tree) view's SVG.
   ========================================================================== */
function layout(expanded, focus, N = NODE, A = ADJ) {
  const ids = [...expanded].filter((i) => N[i]);
  const fl = laneOf(N[focus]);

  const cols = {};
  ids.forEach((id) => { const c = laneOf(N[id]); (cols[c] = cols[c] || []).push(id); });

  /* discovery order + anchor: what pulled each node onto the canvas */
  const order = {}, anchor = {};
  let q = [focus], seen = new Set([focus]), i = 0;
  order[focus] = i++;
  while (q.length) {
    const cur = q.shift();
    (A[cur] || []).filter((a) => expanded.has(a.id) && !seen.has(a.id))
      .forEach((a) => { seen.add(a.id); anchor[a.id] = cur; order[a.id] = i++; q.push(a.id); });
  }
  ids.forEach((id) => { if (order[id] === undefined) order[id] = 9999; });

  const pos = {};
  /* place columns nearest the focus lane first, so anchors exist before
     the cards that hang off them */
  const keys = Object.keys(cols).map(Number).sort((a, b) => Math.abs(a - fl) - Math.abs(b - fl));
  keys.forEach((c) => {
    const items = cols[c]
      .map((id) => ({ id, want: pos[anchor[id]]?.y ?? 0, ord: order[id] }))
      .sort((a, b) => a.want - b.want || a.ord - b.ord);

    /* pin each card to its anchor's height, then sweep downward so no two
       overlap (never closer than one full card + gap) */
    items.forEach((it, idx) => {
      it.y = idx === 0 ? it.want : Math.max(it.want, items[idx - 1].y + STEP);
    });

    /* recentre the whole stack on the average anchor height to cut drift */
    const meanWant = items.reduce((s, it) => s + it.want, 0) / (items.length || 1);
    const meanY = items.reduce((s, it) => s + it.y, 0) / (items.length || 1);
    const shift = meanWant - meanY;
    const x = (c - fl) * CW;
    items.forEach((it) => { pos[it.id] = { x, y: it.y + shift }; });
  });
  /* Normalize so the focused node sits at the origin (0,0). The Graph centres the
     origin in the viewport, so this guarantees Reset/focus always brings the
     focused node itself to the middle of the window. */
  const fp = pos[focus];
  if (fp) ids.forEach((id) => { if (pos[id]) pos[id] = { x: pos[id].x - fp.x, y: pos[id].y - fp.y }; });
  return pos;
}

