/* Door-module (DCM) part numbers — today one distinct SKU per door — and the variance / consolidation decision note,
   captured for the hardware-strategy review. Rendered as an informational banner on each DCM ECU requirements page. */
const DCM_PARTNO = { "ECU-DCM-FL": "4ME 959 793", "ECU-DCM-FR": "4ME 959 792", "ECU-DCM-RL": "4ME 959 795", "ECU-DCM-RR": "4ME 959 794" };
const DCM_VARIANCE_NOTE = "The four door modules currently ship as four distinct part numbers (FL 4ME 959 793 · FR 4ME 959 792 · RL 4ME 959 795 · RR 4ME 959 794) — one SKU per door — even though the connector pin-outs are near-identical within each pair. The differences are wiring-driven only: the front doors carry the exterior mirror (plus fuel-door release on FL); the rear doors carry seat adjustment, sun-blind and seat heating; all four share window lifter, central locking, keyless entry, memory and lighting. Consolidation options for the hardware-strategy review: (1) one ambidextrous DCM — superset connector, function enabled by per-door coding — lowest part-number and software variance; (2) two variants (front / rear); (3) keep four SKUs (status quo, highest variance).";

/* ICD tool — editable connector pin-out for one ECU. Seeds from the derived (HW-requirement) pin-out,
   writes edits/imports to ICD_STORE for that ECU, and offers Upload / Download. Mirrors the K-Matrix tool. */
function IcdTool({ ecuId, tag = "", derivedGroups = [], canWrite = false, onChange }) {
  const [open, setOpen] = useState(false);
  const [, setV] = useState(0);
  const bump = () => { setV((x) => x + 1); if (onChange) onChange(); };
  const btnS = { fontSize: 10, fontWeight: 600, color: "#175CD3", border: "1px solid #B2CCFF", borderRadius: 6, padding: "3px 9px", background: "#fff", cursor: "pointer", whiteSpace: "nowrap" };
  const zBtn = { fontSize: 12, fontWeight: 700, color: "#475467", border: "1px solid #E4E7EC", borderRadius: 5, width: 22, height: 20, background: "#fff", cursor: "pointer", lineHeight: 1 };
  const thS = { textAlign: "left", padding: "3px 6px", background: "#F2F4F7", color: "#475467", fontWeight: 700, border: "1px solid #E4E7EC", fontSize: 9.5 };
  const tdS = { padding: "3px 6px", border: "1px solid #EAECF0", color: "#344054", verticalAlign: "top" };
  const seed = () => { if (!ICD_STORE.data[ecuId]) ICD_STORE.data[ecuId] = JSON.parse(JSON.stringify(derivedGroups || [])); return ICD_STORE.data[ecuId]; };
  const groups = ICD_STORE.data[ecuId] || derivedGroups || [];
  const edited = !!ICD_STORE.data[ecuId];
  const setCell = (gi, ri, key, v, num) => { const gs = seed(); gs[gi].rows[ri][key] = num ? (Number(v) || 0) : v; bump(); };
  const setConn = (gi, v) => { const gs = seed(); gs[gi].conn = v; bump(); };
  const addRow = (gi) => { const gs = seed(); gs[gi].rows.push({ signal: "New signal", pins: 1, cls: "—", dir: "In", wired: "—", from: "—" }); bump(); };
  const delRow = (gi, ri) => { const gs = seed(); gs[gi].rows.splice(ri, 1); if (!gs[gi].rows.length) gs.splice(gi, 1); bump(); };
  const addConn = () => { const gs = seed(); gs.push({ conn: "X-NEW (connector)", rows: [{ signal: "New signal", pins: 1, cls: "—", dir: "In", wired: "—", from: "—" }] }); bump(); };
  const revert = () => { delete ICD_STORE.data[ecuId]; bump(); };
  const exportIcd = async () => {
    const aoa = icdRowsToAoa(groups); const fname = "ICD_" + (tag || ecuId).replace(/[^A-Za-z0-9]+/g, "_");
    let XLSX; try { XLSX = await ensureXLSXLib(); } catch (e) {
      const csv = aoa.map((r) => r.map((v) => '"' + String(v == null ? "" : v).replace(/"/g, '""') + '"').join(",")).join("\n");
      mfmDownload(fname + ".csv", csv, "text/csv;charset=utf-8"); return;
    }
    try { const wb = XLSX.utils.book_new(); const ws = XLSX.utils.aoa_to_sheet(aoa); ws["!cols"] = [{ wch: 26 }, { wch: 42 }, { wch: 6 }, { wch: 12 }, { wch: 6 }, { wch: 26 }, { wch: 18 }]; XLSX.utils.book_append_sheet(wb, ws, "ICD"); XLSX.writeFile(wb, fname + ".xlsx"); }
    catch (e) { alert("Could not build the ICD Excel. " + (e && e.message ? e.message : e)); }
  };
  const fileRef = useRef(null);
  const importIcd = async (file) => {
    if (!file) return;
    let XLSX; try { XLSX = await ensureXLSXLib(); } catch (e) { alert("Excel library unavailable (offline?)."); return; }
    try {
      const buf = await file.arrayBuffer(); const wb = XLSX.read(buf, { type: "array" });
      const sheet = wb.Sheets[wb.SheetNames.find((n) => /icd|pin/i.test(n)) || wb.SheetNames[0]];
      if (!sheet) { alert("No sheet found."); return; }
      const aoa = XLSX.utils.sheet_to_json(sheet, { header: 1, blankrows: false, defval: "" });
      const parsed = icdAoaToGroups(aoa);
      if (!parsed.length) { alert("Could not read any pin-out rows. Expected columns: Connector, Signal/Interface, Pins, Class, Dir, Wired to, From."); return; }
      ICD_STORE.data[ecuId] = parsed; bump();
      alert("Imported " + parsed.reduce((s, g) => s + g.rows.length, 0) + " pins across " + parsed.length + " connector(s).");
    } catch (e) { alert("Import failed: " + (e && e.message ? e.message : e)); }
  };
  const inpS = (w) => ({ width: w || "100%", boxSizing: "border-box", border: "1px solid #E4E7EC", borderRadius: 4, padding: "2px 4px", fontSize: 11, background: canWrite ? "#fff" : "#F9FAFB" });
  const TIN = (val, on, w) => <input disabled={!canWrite} value={val} onChange={(e) => on(e.target.value)} style={inpS(w)} />;
  const NIN = (val, on) => <input type="number" disabled={!canWrite} value={val} onChange={(e) => on(e.target.value)} style={{ ...inpS(56), textAlign: "center" }} />;
  return (
    <>
      <div className="flex items-center flex-wrap" style={{ gap: 8, marginTop: 6 }}>
        <button onClick={() => setOpen(true)} title="Open the connector pin-out (ICD) — view, edit, import and export" style={btnS}>I/O — open / edit</button>
        {edited && <span style={{ fontSize: 9.5, color: "#B54708" }} title="This ECU's ICD has local edits/imports overriding the requirement-derived pin-out">edited{canWrite ? " · " : ""}{canWrite && <button onClick={revert} style={{ color: "#175CD3", fontSize: 9.5 }}>revert to derived</button>}</span>}
      </div>
      {open && (
        <div onClick={() => setOpen(false)} style={{ position: "fixed", inset: 0, background: "rgba(16,24,40,0.45)", zIndex: 1000, display: "flex", alignItems: "center", justifyContent: "center", padding: 20 }}>
          <div onClick={(e) => e.stopPropagation()} style={{ background: "#fff", borderRadius: 10, width: "min(1040px, 96vw)", maxHeight: "90vh", display: "flex", flexDirection: "column", boxShadow: "0 12px 48px rgba(0,0,0,0.32)" }}>
            <div className="flex items-center justify-between" style={{ padding: "10px 14px", borderBottom: "1px solid #EAECF0" }}>
              <div style={{ fontWeight: 700, color: "#101828", fontSize: 13 }}>ECU ICD · connector pin-out {tag ? "· " + tag : ""} <span style={{ fontWeight: 400, color: "#98A2B3", fontSize: 11 }}>{canWrite ? (edited ? "· edited (overrides the requirement-derived pin-out)" : "· derived from hardware requirements — edit to override") : "· read-only (Viewer)"}</span></div>
              <div className="flex items-center gap-2">
                <input ref={fileRef} type="file" accept=".xlsx,.xls,.csv" style={{ display: "none" }} onChange={(e) => { const f = e.target.files && e.target.files[0]; e.target.value = ""; importIcd(f); }} />
                {canWrite && <button onClick={() => fileRef.current && fileRef.current.click()} title="Import an ICD Excel/CSV — replaces this ECU's pin-out" style={{ ...btnS, color: "#B54708", borderColor: "#F0C9A0" }}>Import</button>}
                <button onClick={exportIcd} title="Export this ECU's ICD as Excel" style={btnS}>Export</button>
                <button onClick={() => setOpen(false)} style={{ ...btnS, color: "#344054", borderColor: "#D0D5DD" }}>Close</button>
              </div>
            </div>
            <div style={{ overflow: "auto", padding: 12 }}>
              {groups.length === 0 ? <div style={{ fontSize: 12, color: "#98A2B3" }}>No pin-out yet. {canWrite ? "Add a connector to start, or Import an ICD file." : ""}</div> : groups.map((g, gi) => (
                <div key={gi} style={{ marginBottom: 12, border: "1px solid #EAECF0", borderRadius: 8, overflow: "hidden" }}>
                  <div className="flex items-center justify-between" style={{ padding: "5px 10px", background: "#F9FAFB", borderBottom: "1px solid #EAECF0" }}>
                    <div style={{ minWidth: 240 }}>{canWrite ? TIN(g.conn, (v) => setConn(gi, v), 260) : <span style={{ fontSize: 11.5, fontWeight: 700, color: "#175CD3" }}>{g.conn}</span>}</div>
                    <span style={{ fontSize: 10, color: "#98A2B3" }}>{g.rows.reduce((s, r) => s + (Number(r.pins) || 1), 0)} pin(s)</span>
                  </div>
                  <table style={{ borderCollapse: "collapse", width: "100%", fontSize: 11 }}>
                    <thead><tr>{["Signal / Interface", "Pins", "Class", "Dir", "Wired to", "From"].map((h) => <th key={h} style={thS}>{h}</th>)}{canWrite && <th style={thS}></th>}</tr></thead>
                    <tbody>
                      {g.rows.map((r, ri) => (
                        <tr key={ri}>
                          <td style={{ ...tdS, minWidth: 220 }}>{TIN(r.signal, (v) => setCell(gi, ri, "signal", v))}</td>
                          <td style={{ ...tdS, width: 60 }}>{NIN(r.pins, (v) => setCell(gi, ri, "pins", v, true))}</td>
                          <td style={{ ...tdS, width: 100 }}>{TIN(r.cls, (v) => setCell(gi, ri, "cls", v), 96)}</td>
                          <td style={{ ...tdS, width: 56 }}>{TIN(r.dir, (v) => setCell(gi, ri, "dir", v), 52)}</td>
                          <td style={{ ...tdS, minWidth: 150 }}>{TIN(r.wired, (v) => setCell(gi, ri, "wired", v))}</td>
                          <td style={{ ...tdS, width: 130, fontFamily: "ui-monospace, monospace", fontSize: 9.5, color: "#98A2B3" }}>{TIN(r.from, (v) => setCell(gi, ri, "from", v), 122)}</td>
                          {canWrite && <td style={tdS}><button onClick={() => delRow(gi, ri)} title="Delete this pin/row" style={{ ...zBtn, color: "#B42318", borderColor: "#F0C0BA", width: 20 }}>✕</button></td>}
                        </tr>
                      ))}
                    </tbody>
                  </table>
                  {canWrite && <button onClick={() => addRow(gi)} style={{ ...btnS, margin: "6px 0 8px 10px" }}>+ Add pin</button>}
                </div>
              ))}
              {canWrite && <button onClick={addConn} style={btnS}>+ Add connector</button>}
              <div style={{ fontSize: 10, color: "#98A2B3", marginTop: 8 }}>{canWrite ? "The pin-out is seeded from this ECU's hardware requirements. Edits and imports override the derived ICD for this ECU and flow to the section table and the supplier export. Use “revert to derived” to drop the override." : "Viewers cannot edit the ICD. Ask an Owner to make changes."}</div>
            </div>
          </div>
        </div>
      )}
    </>
  );
}
/* K-Matrix tool — the aggregate communication matrix (Vector-style), collecting the message/signal
   definitions from every L1's Interfaces & Signals. Editable (Owner) and synchronized to the ARXML and
   Excel exports. Rendered under each ECU's Network Topology; the ARXML is generated from this matrix. */
function KMatrixTool({ canWrite = false, onL1, ecuId, openReq = null, onOpenHandled }) {
  const [kmOpen, setKmOpen] = useState(false);
  const [, setKmV] = useState(0);
  // Open the modal in one step when an external request targets this ECU (e.g. clicking a frame in the Impact view).
  useEffect(() => { if (openReq && openReq === ecuId) { setKmOpen(true); onOpenHandled && onOpenHandled(); } }, [openReq, ecuId]); // eslint-disable-line
  const dl = mfmDownload;
  const btnS = { fontSize: 10, fontWeight: 600, color: "#175CD3", border: "1px solid #B2CCFF", borderRadius: 6, padding: "3px 9px", background: "#fff", cursor: "pointer", whiteSpace: "nowrap" };
  const zBtn = { fontSize: 12, fontWeight: 700, color: "#475467", border: "1px solid #E4E7EC", borderRadius: 5, width: 22, height: 20, background: "#fff", cursor: "pointer", lineHeight: 1 };
  const thS = { textAlign: "left", padding: "3px 6px", background: "#F2F4F7", color: "#475467", fontWeight: 700, border: "1px solid #E4E7EC", fontSize: 9.5 };
  const tdS = { padding: "3px 6px", border: "1px solid #EAECF0", color: "#344054", verticalAlign: "top" };
  const genKMatrix = async () => {
    const d = kmatrixData();
    let XLSX;
    try { XLSX = await ensureXLSXLib(); } catch (e) {
      const csv = d.matrix.map((r) => r.map((v) => '"' + String(v == null ? "" : v).replace(/"/g, '""').replace(/\n/g, "; ") + '"').join(",")).join("\n");
      dl("K-Matrix.csv", csv, "text/csv;charset=utf-8"); return;
    }
    try {
      const wb = XLSX.utils.book_new();
      const wsI = XLSX.utils.aoa_to_sheet(d.index); wsI["!cols"] = [{ wch: 26 }, { wch: 14 }, { wch: 7 }];
      XLSX.utils.book_append_sheet(wb, wsI, "Messages");
      const wsM = XLSX.utils.aoa_to_sheet(d.matrix); wsM["!merges"] = d.merges;
      wsM["!cols"] = [24, 12, 10, 13, 12, 9, 11, 28, 8, 8, 9, 9, 9, 9, 9, 8, 9, 9, 8, 8, 9, 9, 7, 30, 18, 22].map((wch) => ({ wch }));
      XLSX.utils.book_append_sheet(wb, wsM, "K-Matrix");
      XLSX.writeFile(wb, "K-Matrix.xlsx");
    } catch (e) { alert("Could not build the K-Matrix Excel. " + (e && e.message ? e.message : e)); }
  };
  const KM = KM_STORE.data;
  const viewMsgs = kmMsgsForEcu(ecuId); // this ECU's Tx/Rx subset of the cluster matrix (all messages when ecuId is absent)
  const kmBump = () => setKmV((v) => v + 1);
  const setMsgField = (mi, key, v, num) => { KM.msgs[mi][key] = num ? (v === "" ? null : Number(v)) : v; kmBump(); };
  const setSigField = (mi, si, idx, v, num) => { KM.msgs[mi].sig[si][idx] = num ? (Number(v) || 0) : v; kmBump(); };
  const setSigMux = (mi, si, v) => { const t = String(v).trim(); KM.msgs[mi].sig[si][4] = t === "" ? undefined : (/^m$/i.test(t) ? "M" : (isFinite(Number(t)) ? Number(t) : t)); kmBump(); };
  const setLinField = (cm, pos, v, num) => { const e = KM.lin.find((x) => x[0] === cm); if (e) e[pos] = num ? Number(v) : v; kmBump(); };
  const addMsg = () => { const short = KM_ECU_TO_SHORT(ecuId); const ids = new Set(KM.msgs.map((m) => m.id)); let nid = 1; while (ids.has(nid)) nid++; const names = new Set(KM.msgs.map((m) => m.name)); let nm = "New_Message", k = 1; while (names.has(nm)) nm = "New_Message_" + (++k); KM.msgs.push({ name: nm, id: nid, ext: true, dir: "Tx", cyc: null, dlc: 8, sig: [["New_Signal", 0, 8, null]], note: "", sender: short || undefined, recv: [] }); kmBump(); };
  const delMsg = (mi) => { KM.msgs.splice(mi, 1); kmBump(); };
  const addSig = (mi) => { const m = KM.msgs[mi]; const used = new Set(m.sig.map((s) => s[0])); let sn = "New_Signal", k = 1; while (used.has(sn)) sn = "New_Signal_" + (++k); const last = m.sig.reduce((mx, s) => Math.max(mx, (s[1] || 0) + (s[2] || 0)), 0); m.sig.push([sn, last, 8, null]); kmBump(); };
  const delSig = (mi, si) => { const m = KM.msgs[mi]; m.sig.splice(si, 1); if (m.sig.length === 0) KM.msgs.splice(mi, 1); kmBump(); };
  /* Auto-pack (#8): reassign every signal's start bit — base signals sequentially from bit 0, then each multiplex
     group overlaid after the base region — and grow DLC to fit. Fixes the overlaps/gaps/overflow the consistency engine flags. */
  const autoPack = () => {
    if (typeof window !== "undefined" && window.confirm && !window.confirm("Auto-pack reassigns every signal's start bit in this cluster (base signals first, then multiplex groups) and grows DLC to fit. Tip: capture a Baseline first if you want to keep the current layout. Continue?")) return;
    let packed = 0, grew = 0, overflow = 0;
    KM.msgs.forEach((m) => {
      const sig = m.sig || []; if (!sig.length) return;
      const base = sig.filter((s) => s[4] === undefined || s[4] === null || s[4] === "M");
      const groups = {}; sig.forEach((s) => { if (typeof s[4] === "number") (groups[s[4]] = groups[s[4]] || []).push(s); });
      let cur = 0; base.forEach((s) => { s[1] = cur; cur += Math.max(1, Number(s[2]) || 0); });
      const baseEnd = cur; let maxEnd = baseEnd;
      Object.keys(groups).sort((a, b) => a - b).forEach((g) => { let c = baseEnd; groups[g].forEach((s) => { s[1] = c; c += Math.max(1, Number(s[2]) || 0); }); maxEnd = Math.max(maxEnd, c); });
      const need = Math.ceil(maxEnd / 8);
      if ((m.dlc || 0) < need) { m.dlc = Math.min(64, need); grew++; }
      if (need > 8) overflow++;
      packed++;
    });
    kmBump();
    if (typeof window !== "undefined" && window.alert) window.alert("Auto-packed " + packed + " frame" + (packed === 1 ? "" : "s") + (grew ? " · grew DLC on " + grew : "") + (overflow ? " · " + overflow + " exceed 8 bytes (CAN-FD/verify)" : "") + ".");
  };
  /* Interop export (#7): generate a Vector CAN database (.dbc) and a LIN Description File (.ldf) from the live K-Matrix. */
  const nodeName = (n) => (n && String(n).replace(/[^A-Za-z0-9_]/g, "_")) || "Vector__XXX";
  const canId = (m) => ((m.ext ? (0x80000000 | (m.id || 0)) : (m.id || 0)) >>> 0);
  const exportDbc = () => {
    const msgs = KM_STORE.data.msgs || [];
    const nodes = Array.from(new Set(msgs.flatMap((m) => [m.sender, ...(m.recv || [])]).filter(Boolean).map(nodeName)));
    let out = 'VERSION ""\n\n\nNS_ :\n\nBS_:\n\n';
    out += "BU_: " + (nodes.join(" ") || "Vector__XXX") + "\n\n";
    msgs.forEach((m) => {
      out += "BO_ " + canId(m) + " " + nodeName(m.name) + ": " + (m.dlc || 8) + " " + nodeName(m.sender) + "\n";
      (m.sig || []).forEach((s) => { const mux = s[4]; const mtok = mux === "M" ? " M" : (typeof mux === "number" ? " m" + mux : ""); const recv = (m.recv || []).map(nodeName); out += " SG_ " + nodeName(s[0]) + mtok + " : " + (s[1] || 0) + "|" + (s[2] || 1) + "@1+ (1,0) [0|0] \"\" " + (recv.join(",") || "Vector__XXX") + "\n"; });
      out += "\n";
    });
    msgs.forEach((m) => { if (m.l1) out += 'CM_ BO_ ' + canId(m) + ' "L1: ' + String(m.l1).replace(/"/g, "'") + '";\n'; });
    dl("cluster.dbc", out, "text/plain;charset=utf-8");
  };
  const exportLdf = () => {
    const msgs = KM_STORE.data.msgs || [];
    const allNodes = Array.from(new Set(msgs.flatMap((m) => [m.sender, ...(m.recv || [])]).filter(Boolean).map(nodeName)));
    const cnt = {}; msgs.forEach((m) => { if (m.sender) cnt[nodeName(m.sender)] = (cnt[nodeName(m.sender)] || 0) + 1; });
    const master = Object.keys(cnt).sort((a, b) => cnt[b] - cnt[a])[0] || "Master";
    const slaves = allNodes.filter((n) => n !== master);
    let out = "/* LIN Description File — generated scaffold from the K-Matrix. Review master/slave roles, frame IDs (masked to 6 bits), signal sizes (LIN scalar ≤16 bits) and the schedule before production use. */\n";
    out += 'LIN_description_file;\nLIN_protocol_version = "2.1";\nLIN_language_version = "2.1";\nLIN_speed = 19.2 kbps;\n\n';
    out += "Nodes {\n  Master: " + master + ", 5 ms, 0.1 ms ;\n  Slaves: " + (slaves.join(", ") || master) + " ;\n}\n\n";
    out += "Signals {\n";
    msgs.forEach((m) => { const pub = nodeName(m.sender) || master; const subs = (m.recv || []).map(nodeName); (m.sig || []).forEach((s) => { out += "  " + nodeName(s[0]) + ": " + (s[2] || 1) + ", 0, " + pub + (subs.length ? ", " + subs.join(", ") : "") + " ;\n"; }); });
    out += "}\n\n";
    out += "Frames {\n";
    msgs.forEach((m) => { const fid = (m.id || 0) & 0x3F; out += "  " + nodeName(m.name) + ": 0x" + fid.toString(16).toUpperCase() + ", " + (nodeName(m.sender) || master) + ", " + Math.min(8, m.dlc || 8) + " {\n"; (m.sig || []).forEach((s) => { out += "    " + nodeName(s[0]) + ", " + (s[1] || 0) + " ;\n"; }); out += "  }\n"; });
    out += "}\n\n";
    out += "Schedule_Tables {\n  Cyclic {\n";
    msgs.forEach((m) => { out += "    " + nodeName(m.name) + " delay " + (m.cyc || 10) + " ms ;\n"; });
    out += "  }\n}\n";
    dl("cluster.ldf", out, "text/plain;charset=utf-8");
  };
  const kmFileRef = useRef(null);
  const importKMatrix = async (file) => {
    if (!file) return;
    let XLSX; try { XLSX = await ensureXLSXLib(); } catch (e) { alert("Excel library unavailable (offline?)."); return; }
    try {
      const buf = await file.arrayBuffer();
      const wb = XLSX.read(buf, { type: "array" });
      const name = wb.SheetNames.find((n) => /k-?matrix/i.test(n)) || wb.SheetNames[wb.SheetNames.length - 1];
      const sheet = wb.Sheets[name];
      if (!sheet) { alert("No K-Matrix sheet found in the workbook."); return; }
      const aoa = XLSX.utils.sheet_to_json(sheet, { header: 1, blankrows: false, defval: "" });
      const parsed = parseKMatrixAoa(aoa);
      if (!parsed.msgs.length) { alert("Could not read any messages from the sheet. Expected the K-Matrix export layout."); return; }
      KM_STORE.data = parsed; kmBump();
      alert("Imported " + parsed.msgs.length + " messages (" + parsed.msgs.reduce((s, m) => s + m.sig.length, 0) + " signals). Applied everywhere.");
    } catch (e) { alert("Import failed: " + (e && e.message ? e.message : e)); }
  };
  const busFileRef = useRef(null);
  const importBus = async (file) => {
    if (!file) return;
    try {
      const text = await file.text();
      const { fmt, parsed } = parseBusFile(file.name, text);
      if (!parsed || !parsed.msgs || !parsed.msgs.length) { alert("No CAN/LIN messages found in " + file.name + ".\n\nDBC and LDF are fully supported; ARXML import is best-effort (CAN frames + I-signal PDU mappings)."); return; }
      const r = mergeBusIntoKM(parsed.msgs, fmt); kmBump();
      alert("Imported " + file.name + " (" + fmt + "):\n" + r.added + " new message(s), " + r.updated + " updated, " + r.signals + " signal(s).\n\nMerged into the K-Matrix — applied to the ARXML and all exports. The file stayed in your browser (nothing uploaded).");
    } catch (e) { alert("Import failed: " + (e && e.message ? e.message : e)); }
  };
  const kmJsonRef = useRef(null);
  const saveKmJson = () => dl("K-Matrix.json", JSON.stringify(KM_STORE.data, null, 2), "application/json");
  const loadKmJson = async (file) => {
    if (!file) return;
    try {
      const parsed = JSON.parse(await file.text());
      if (!parsed || !Array.isArray(parsed.msgs) || !Array.isArray(parsed.lin) || !Array.isArray(parsed.txt)) { alert("Not a valid K-Matrix JSON (expected msgs, lin, txt arrays)."); return; }
      if (!Array.isArray(parsed.run)) parsed.run = KM_STORE.data.run;
      KM_STORE.data = parsed; kmBump();
      alert("Loaded " + parsed.msgs.length + " messages from JSON. Applied everywhere.");
    } catch (e) { alert("Load failed: " + (e && e.message ? e.message : e)); }
  };
  return (
    <>
      <div className="flex items-center flex-wrap" style={{ gap: 8, marginTop: 6 }}>
        <button onClick={() => setKmOpen(true)} title="Open the aggregate K-Matrix — editable; Upload/Download inside; changes apply to the ARXML everywhere" style={btnS}>K-Matrix — open / edit</button>
        <button onClick={() => dl("complete.arxml", buildDcmFlArxml(), "application/xml")} title="Complete ARXML generated from the K-Matrix — CAN cluster, frames/PDUs with exact IDs, signals + encodings, ECU instance and SW-C" style={btnS}>Complete ARXML</button>
        <button onClick={mfmGenAutosar} title="Generate AUTOSAR SWC/RTE — C skeleton + ARXML SWC description" style={btnS}>Generate code · AUTOSAR SWC/RTE</button>
        <button onClick={mfmGenSimulink} title="Generate Simulink / Embedded Coder model builder" style={btnS}>Generate code · Simulink/Embedded Coder</button>
      </div>
      {kmOpen && (
        <div onClick={() => setKmOpen(false)} style={{ position: "fixed", inset: 0, background: "rgba(16,24,40,0.45)", zIndex: 1000, display: "flex", alignItems: "center", justifyContent: "center", padding: 20 }}>
          <div onClick={(e) => e.stopPropagation()} style={{ background: "#fff", borderRadius: 10, width: "min(1220px, 97vw)", maxHeight: "90vh", display: "flex", flexDirection: "column", boxShadow: "0 12px 48px rgba(0,0,0,0.32)" }}>
            <div className="flex items-center justify-between" style={{ padding: "10px 14px", borderBottom: "1px solid #EAECF0" }}>
              <div style={{ fontWeight: 700, color: "#101828", fontSize: 13 }}>K-Matrix · {ecuId ? KM_ECU_TO_SHORT(ecuId) + " communication matrix" : "aggregate communication matrix"} <span style={{ fontWeight: 400, color: "#98A2B3", fontSize: 11 }}>{ecuId ? "· this ECU's Tx/Rx frames (" + viewMsgs.length + " of " + KM.msgs.length + ") · edits apply to the shared cluster matrix" : (canWrite ? "· collected from every L1's Interfaces & Signals · edits apply everywhere (ARXML, Excel, exports)" : "· read-only (Viewer)")}</span></div>
              <div className="flex items-center gap-2">
                <input ref={kmFileRef} type="file" accept=".xlsx,.xls" style={{ display: "none" }} onChange={(e) => { const f = e.target.files && e.target.files[0]; e.target.value = ""; importKMatrix(f); }} />
                <input ref={busFileRef} type="file" accept=".dbc,.ldf,.arxml,.xml" style={{ display: "none" }} onChange={(e) => { const f = e.target.files && e.target.files[0]; e.target.value = ""; importBus(f); }} />
                {canWrite && <button onClick={autoPack} title="Auto-assign every signal's start bit (base then mux groups) and grow DLC to fit — fixes overlaps, gaps and overflow" style={{ ...btnS, color: "#067647", borderColor: "#A6F4C5" }}>Auto-pack bits</button>}
                {canWrite && <button onClick={() => busFileRef.current && busFileRef.current.click()} title="Import a real bus database — DBC, LDF or ARXML — and merge its ECUs, messages and signals into the K-Matrix. Parsed in your browser; the file is never uploaded." style={{ ...btnS, color: "#0E7090", borderColor: "#7CD4FD" }}>Import DBC/LDF/ARXML</button>}
                {canWrite && <button onClick={() => kmFileRef.current && kmFileRef.current.click()} title="Import a K-Matrix Excel file — replaces the live data (use for major changes)" style={{ ...btnS, color: "#B54708", borderColor: "#F0C9A0" }}>Import Excel</button>}
                <button onClick={genKMatrix} title="Export the current K-Matrix as Excel" style={btnS}>Export</button>
                <button onClick={exportDbc} title="Export a Vector CAN database (.dbc) from the current K-Matrix" style={{ ...btnS, color: "#7A5AF8", borderColor: "#D9D6FE" }}>DBC</button>
                <button onClick={exportLdf} title="Export a LIN Description File (.ldf) scaffold from the current K-Matrix" style={{ ...btnS, color: "#7A5AF8", borderColor: "#D9D6FE" }}>LDF</button>
                <button onClick={() => setKmOpen(false)} style={{ ...btnS, color: "#344054", borderColor: "#D0D5DD" }}>Close</button>
              </div>
            </div>
            <div style={{ overflow: "auto", padding: 12 }}>
              <table style={{ borderCollapse: "collapse", width: "100%", fontSize: 11 }}>
                <thead><tr>{["Message", "ID", "Cyc [ms]", "DLC", "Maps to L1", "Signal", "Start bit", "Len", "Mux", "Factor", "Offset", "Unit", "Logical / enum"].map((h) => <th key={h} style={thS}>{h}</th>)}{canWrite && <th style={thS}></th>}</tr></thead>
                <tbody>
                  {viewMsgs.flatMap((m) => { const mi = KM.msgs.indexOf(m); return m.sig.map((sg, si) => {
                    const [sn, st, ln, cm, mux] = sg, lin = KM.lin.find((x) => x[0] === cm), txt = KM.txt.find((x) => x[0] === cm), first = si === 0;
                    const muxVal = mux === "M" ? "M" : (typeof mux === "number" ? String(mux) : ""), isMulti = typeof mux === "number";
                    const inpS = { width: "100%", boxSizing: "border-box", border: "1px solid #E4E7EC", borderRadius: 4, padding: "2px 4px", fontSize: 11, background: canWrite ? "#fff" : "#F9FAFB" };
                    const NIN = (val, on) => <input type="number" step="any" disabled={!canWrite} value={val} onChange={(e) => on(e.target.value)} style={inpS} />;
                    const TIN = (val, on) => <input disabled={!canWrite} value={val} onChange={(e) => on(e.target.value)} style={inpS} />;
                    return (
                      <tr key={mi + "-" + si} style={{ background: first ? "#F9FAFB" : (mux === "M" ? "#FEF6EE" : "#fff") }}>
                        <td style={{ ...tdS, fontWeight: 600, whiteSpace: "nowrap" }}>{first ? m.name : ""}</td>
                        <td style={{ ...tdS, fontFamily: "ui-monospace, monospace", color: "#175CD3" }}>{first ? "0x" + m.id.toString(16).toUpperCase() : ""}</td>
                        <td style={{ ...tdS, width: 64 }}>{first ? NIN(m.cyc == null ? "" : m.cyc, (v) => setMsgField(mi, "cyc", v, true)) : ""}</td>
                        <td style={{ ...tdS, width: 52 }}>{first ? NIN(m.dlc, (v) => setMsgField(mi, "dlc", v, true)) : ""}</td>
                        <td style={{ ...tdS, minWidth: 150, whiteSpace: "nowrap" }}>{first ? (
                          <span className="flex items-center gap-1">
                            {canWrite ? TIN(m.l1 || "", (v) => setMsgField(mi, "l1", v, false)) : <span style={{ fontSize: 11, color: m.l1 ? "#344054" : "#98A2B3" }}>{m.l1 || "—"}</span>}
                            {m.l1 && onL1 && <button onClick={() => onL1(m.l1)} title={"Open " + m.l1 + " L1 requirement"} style={{ color: "#175CD3", fontSize: 12, flexShrink: 0, fontWeight: 700 }}>↗</button>}
                          </span>
                        ) : ""}</td>
                        <td style={{ ...tdS, minWidth: 200, paddingLeft: isMulti ? 18 : undefined }}>{mux === "M" && <span style={{ color: "#B54708", fontWeight: 700, marginRight: 4 }} title="Multiplexor selector">◈</span>}{isMulti && <span style={{ color: "#98A2B3", marginRight: 3 }}>↳</span>}{TIN(sn, (v) => setSigField(mi, si, 0, v, false))}</td>
                        <td style={{ ...tdS, width: 64 }}>{NIN(st, (v) => setSigField(mi, si, 1, v, true))}</td>
                        <td style={{ ...tdS, width: 52 }}>{NIN(ln, (v) => setSigField(mi, si, 2, v, true))}</td>
                        <td style={{ ...tdS, width: 48 }} title="M = multiplexor selector · number = mux group · blank = always present">{TIN(muxVal, (v) => setSigMux(mi, si, v))}</td>
                        <td style={{ ...tdS, width: 66 }}>{lin ? NIN(lin[1], (v) => setLinField(cm, 1, v, true)) : "—"}</td>
                        <td style={{ ...tdS, width: 66 }}>{lin ? NIN(lin[2], (v) => setLinField(cm, 2, v, true)) : "—"}</td>
                        <td style={{ ...tdS, width: 58 }}>{lin ? TIN(lin[3], (v) => setLinField(cm, 3, v, false)) : ""}</td>
                        <td style={{ ...tdS, color: "#667085", maxWidth: 280 }}>{txt ? Object.entries(txt[1]).map(([k, val]) => k + "=" + val).join(", ") : (lin ? "" : "raw / opaque")}</td>
                        {canWrite && <td style={{ ...tdS, whiteSpace: "nowrap" }}>
                          <button onClick={() => delSig(mi, si)} title="Delete this signal" style={{ ...zBtn, color: "#B42318", borderColor: "#F0C0BA", width: 20 }}>✕</button>
                          {first && <button onClick={() => addSig(mi)} title="Add a signal to this message" style={{ ...zBtn, color: "#175CD3", borderColor: "#B2CCFF", width: 20, marginLeft: 3 }}>+</button>}
                          {first && <button onClick={() => delMsg(mi)} title="Delete this whole message" style={{ ...zBtn, color: "#B42318", borderColor: "#F0C0BA", width: 40, marginLeft: 3, fontSize: 9 }}>✕ msg</button>}
                        </td>}
                      </tr>
                    );
                  }); })}
                </tbody>
              </table>
              {canWrite && <button onClick={addMsg} title="Add a new message" style={{ ...btnS, marginTop: 8 }}>+ Add message</button>}
              <div style={{ fontSize: 10, color: "#98A2B3", marginTop: 8 }}>{canWrite ? "The K-Matrix aggregates the message/signal definitions from every L1's Interfaces & Signals. Edits, added/deleted rows and Excel imports save to the single K-Matrix source and flow to the ARXML, the Excel export and the in-app matrix. Enum/logical tables are read-only here (set them via Excel import)." : "Viewers cannot edit the K-Matrix. Ask an Owner to make changes."}</div>
            </div>
          </div>
        </div>
      )}
    </>
  );
}
/* Interface & signal spec (Blocks + Signal flows tables) — rendered under the "Interfaces & signals" L2. */
function MirrorIfaceSpec() {
  const M = MIRROR_FBM, B = M.blocks;
  const thS = { textAlign: "left", padding: "3px 6px", background: "#F2F4F7", color: "#475467", fontWeight: 700, border: "1px solid #E4E7EC", fontSize: 9.5 };
  const tdS = { padding: "3px 6px", border: "1px solid #EAECF0", color: "#344054", verticalAlign: "top" };
  return (
    <div style={{ border: "1px solid #E4E7EC", borderRadius: 8, background: "#F8FAFC", padding: 8, marginTop: 10, overflowX: "auto" }}>
      <div style={{ fontSize: 9.5, fontWeight: 700, color: "#98A2B3", letterSpacing: 0.3, marginBottom: 6 }}>INTERFACE &amp; SIGNAL SPEC · {M.title.toUpperCase()}</div>
      <div style={{ display: "grid", gridTemplateColumns: "1fr", gap: 10 }}>
        <div>
          <div style={{ fontSize: 9, fontWeight: 700, color: "#98A2B3", letterSpacing: 0.3, marginBottom: 3 }}>BLOCKS · {Object.keys(B).length} (ECU / actor / actuator)</div>
          <table style={{ borderCollapse: "collapse", width: "100%", fontSize: 10.5 }}>
            <thead><tr>{["Block", "ECU", "Type", "Controller", "Functions"].map((h) => <th key={h} style={thS}>{h}</th>)}</tr></thead>
            <tbody>
              {Object.entries(B).map(([id, b]) => (
                <tr key={id}>
                  <td style={{ ...tdS, fontWeight: 600 }}>{b.label}</td>
                  <td style={{ ...tdS, fontFamily: "ui-monospace, monospace", color: "#175CD3" }}>{b.ecu || "—"}</td>
                  <td style={tdS}>{b.kind}</td>
                  <td style={tdS}>{b.controller || "—"}</td>
                  <td style={{ ...tdS, color: "#667085" }}>{(b.fns || []).join(" · ") || "—"}</td>
                </tr>
              ))}
            </tbody>
          </table>
        </div>
        <div>
          <div style={{ fontSize: 9, fontWeight: 700, color: "#98A2B3", letterSpacing: 0.3, marginBottom: 3 }}>SIGNAL FLOWS · {M.flows.length}</div>
          <table style={{ borderCollapse: "collapse", width: "100%", fontSize: 10.5 }}>
            <thead><tr>{["#", "From → To", "Interaction", "Bus / Signal"].map((h) => <th key={h} style={thS}>{h}</th>)}</tr></thead>
            <tbody>
              {M.flows.map((f, i) => (
                <tr key={i}>
                  <td style={tdS}>{i + 1}</td>
                  <td style={{ ...tdS, fontWeight: 600 }}>{f.from} → {Array.isArray(f.to) ? f.to.join(", ") : (f.to || "—")}</td>
                  <td style={{ ...tdS, color: "#5925DC", fontWeight: 600 }}>{f.interaction || f.type}</td>
                  <td style={{ ...tdS, fontFamily: "ui-monospace, monospace", color: "#344054" }}>{f.bus || f.signal || "—"}</td>
                </tr>
              ))}
            </tbody>
          </table>
        </div>
      </div>
    </div>
  );
}
/* Structured numeric timing editor (safe alternative to free-text) — rendered under the "Performance & timing" L2.
   Editing a field updates MIRROR_TIMING (the single source of truth) and rewrites the requirement statement,
   so the ARXML periods, the JSON model, and the requirement text all stay in sync. Owner-only. */
function MirrorTimingEditor({ canWrite, setStmt }) {
  const [t, setT] = useState({ ...MIRROR_TIMING });
  const fields = [
    ["runnablePeriodMs", "DCM runnable period", "ms"],
    ["endToEndMs", "End-to-end (switch → motor)", "ms"],
    ["roundTripMs", "DCM ↔ motor round-trip", "ms"],
    ["settleS", "Mirror travel settle", "s"],
    ["availabilityPct", "Availability", "%"],
  ];
  const set = (k, v) => {
    const num = parseFloat(v);
    const nt = { ...t, [k]: (v === "" || isNaN(num)) ? v : num };
    setT(nt);
    if (v !== "" && !isNaN(num)) { MIRROR_TIMING[k] = num; if (setStmt) setStmt(perfStatement()); }
  };
  return (
    <div style={{ border: "1px solid #E4E7EC", borderRadius: 8, background: "#F8FAFC", padding: 8, marginTop: 10 }}>
      <div style={{ fontSize: 9.5, fontWeight: 700, color: "#98A2B3", letterSpacing: 0.3, marginBottom: 6 }}>TIMING PARAMETERS — single source of truth{canWrite ? "" : " (read-only)"}</div>
      <div style={{ display: "grid", gridTemplateColumns: "repeat(auto-fit, minmax(150px, 1fr))", gap: 8 }}>
        {fields.map(([k, label, unit]) => (
          <label key={k} style={{ display: "block" }}>
            <div style={{ fontSize: 9.5, color: "#667085", marginBottom: 2 }}>{label}</div>
            <div className="flex items-center gap-1">
              <input type="number" step="any" value={t[k]} disabled={!canWrite}
                onChange={(e) => set(k, e.target.value)}
                className="w-full rounded outline-none px-2 py-1" style={{ fontSize: 12, border: "1px solid #E4E7EC", background: canWrite ? "#fff" : "#F2F4F7", color: "#101828" }} />
              <span style={{ fontSize: 10, color: "#98A2B3", width: 16 }}>{unit}</span>
            </div>
          </label>
        ))}
      </div>
      <div style={{ fontSize: 9, color: "#98A2B3", marginTop: 6 }}>Editing a value rewrites the requirement text above and updates the ARXML TIMING-EVENT periods and JSON model. Derived frequency: {Math.round(1000 / (parseFloat(t.runnablePeriodMs) || 1))} Hz.</div>
    </div>
  );
}
/* Boundary (context) diagram — the system under design in the centre, external actors/systems around it,
   and every interface crossing the boundary. Rendered under the "Boundary Diagram" L2 aspect. */
function BoundaryDiagram() {
  const [zoom, setZoom] = useState(1);
  const boxRef = useRef(null);
  const fit = () => { const el = boxRef.current; const w = el ? el.clientWidth - 6 : 1040; setZoom(Math.max(0.3, Math.min(3, +(w / 1040).toFixed(3)))); };
  useEffect(() => { const id = requestAnimationFrame(fit); const on = () => fit(); window.addEventListener("resize", on); return () => { cancelAnimationFrame(id); window.removeEventListener("resize", on); }; }, []);
  const zBtn = { fontSize: 12, fontWeight: 700, color: "#475467", border: "1px solid #E4E7EC", borderRadius: 5, width: 22, height: 20, background: "#fff", cursor: "pointer", lineHeight: 1 };
  const SYS = { x: 380, y: 228, w: 280, h: 104 };
  const ext = [
    { x: 36, y: 250, w: 150, h: 64, label: "Driver", a: [186, 282], b: [380, 282], dir: "in", flow: "Mirror Adjust Request", sub: "▲ ▼ ◄ ► , Reset" },
    { x: 150, y: 34, w: 196, h: 56, label: "CCU / Vehicle Compute", a: [248, 90], b: [445, 228], dir: "in", flow: "Enable / wake · Vehicle mode", sub: "Center_Platform_CAN01" },
    { x: 566, y: 34, w: 196, h: 56, label: "Center Zone (CZM)", a: [664, 90], b: [600, 228], dir: "both", flow: "Door request / response", sub: "Center_Door_CAN01" },
    { x: 854, y: 150, w: 150, h: 56, label: "Diagnostic Tester", a: [854, 178], b: [660, 258], dir: "both", flow: "UDS diagnostics", sub: "DTC · routines" },
    { x: 854, y: 300, w: 150, h: 56, label: "Power Supply", a: [854, 328], b: [660, 306], dir: "in", flow: "KL30 / KL15", sub: "" },
    { x: 430, y: 470, w: 180, h: 64, label: "Exterior Mirror Motors", a: [520, 470], b: [520, 332], dir: "out", flow: "Position command · Motor status", sub: "H-bridge PWM · feedback" },
  ];
  const conn = (e, i) => {
    const [ax, ay] = e.a, [bx, by] = e.b, mx = (ax + bx) / 2, my = (ay + by) / 2;
    return (
      <g key={"c" + i}>
        <line x1={ax} y1={ay} x2={bx} y2={by} stroke="#5B7794" strokeWidth={1.2} markerStart={(e.dir === "out" || e.dir === "both") ? "url(#bndAr)" : undefined} markerEnd={(e.dir === "in" || e.dir === "both") ? "url(#bndAr)" : undefined} />
        <rect x={mx - 84} y={my - 13} width={168} height={e.sub ? 25 : 15} rx={3} fill="#fff" opacity={0.92} />
        <text x={mx} y={my - 2} fontSize={8.5} fontWeight="600" textAnchor="middle" fill="#1D2939">{e.flow}</text>
        {e.sub && <text x={mx} y={my + 9} fontSize={7.5} textAnchor="middle" fill="#98A2B3">{e.sub}</text>}
      </g>
    );
  };
  return (
    <div style={{ border: "1px solid #E4E7EC", borderRadius: 8, background: "#F8FAFC", padding: 8, marginTop: 10, overflowX: "auto" }}>
      <div className="flex items-center justify-between flex-wrap" style={{ marginBottom: 6, gap: 8 }}>
        <div style={{ fontSize: 9.5, fontWeight: 700, color: "#98A2B3", letterSpacing: 0.3 }}>BOUNDARY (CONTEXT) DIAGRAM · ADJUST EXTERIOR MIRRORS</div>
        <div className="flex items-center gap-1.5" style={{ flexShrink: 0 }}>
          <button onClick={() => setZoom((z) => Math.max(0.3, +(z - 0.2).toFixed(2)))} title="Zoom out" style={zBtn}>−</button>
          <button onClick={() => setZoom((z) => Math.min(3, +(z + 0.2).toFixed(2)))} title="Zoom in" style={zBtn}>+</button>
          <button onClick={fit} title="Fit to page width" style={{ ...zBtn, width: 30 }}>⤢</button>
        </div>
      </div>
      <div ref={boxRef} style={{ overflow: "auto", border: "1px solid #EAECF0", borderRadius: 6, background: "#fff", maxHeight: 640 }}>
        <svg viewBox="0 0 1040 560" width={Math.round(1040 * zoom)} height={Math.round(560 * zoom)} style={{ display: "block" }} xmlns="http://www.w3.org/2000/svg">
          <defs><marker id="bndAr" markerWidth="8" markerHeight="8" refX="6" refY="3" orient="auto"><path d="M0,0 L6,3 L0,6 Z" fill="#5B7794" /></marker></defs>
          {ext.map(conn)}
          {ext.map((e, i) => (
            <g key={"b" + i}>
              <rect x={e.x} y={e.y} width={e.w} height={e.h} rx={6} fill="#F2F4F7" stroke="#B6C0CC" />
              <text x={e.x + e.w / 2} y={e.y + e.h / 2 + 3} fontSize={11} fontWeight="700" textAnchor="middle" fill="#344054">{e.label}</text>
            </g>
          ))}
          <rect x={SYS.x} y={SYS.y} width={SYS.w} height={SYS.h} rx={8} fill="#EAF2FF" stroke="#175CD3" strokeWidth={1.5} />
          <text x={SYS.x + SYS.w / 2} y={SYS.y + 36} fontSize={13} fontWeight="700" textAnchor="middle" fill="#175CD3">Exterior Mirror Adjustment System</text>
          <text x={SYS.x + SYS.w / 2} y={SYS.y + 56} fontSize={10} textAnchor="middle" fill="#475467">DCM_FL / DCM_FR / DCM_RL / DCM_RR</text>
        </svg>
      </div>
    </div>
  );
}
/* Mirror-system architecture diagram (redesigned, cleaned-up version of the platform Simulink model) — the
   mirror function family on the Connected Center Zone: inputs → Center_Door_CAN01 → door module (TSG) →
   the five mirror functions and their drivers/actuators. "Adjusting exterior mirrors" is highlighted as the L1. */
function MirrorArchDiagram() {
  const [zoom, setZoom] = useState(1);
  const boxRef = useRef(null);
  const fit = () => { const el = boxRef.current; const w = el ? el.clientWidth - 6 : 1120; setZoom(Math.max(0.3, Math.min(3, +(w / 1120).toFixed(3)))); };
  useEffect(() => { const id = requestAnimationFrame(fit); const on = () => fit(); window.addEventListener("resize", on); return () => { cancelAnimationFrame(id); window.removeEventListener("resize", on); }; }, []);
  const zBtn = { fontSize: 12, fontWeight: 700, color: "#475467", border: "1px solid #E4E7EC", borderRadius: 5, width: 22, height: 20, background: "#fff", cursor: "pointer", lineHeight: 1 };
  const inputs = [
    { x: 210, l1: "Fold /", l2: "Unfold" },
    { x: 350, l1: "Adjust", l2: "▲ ▼ ◄ ►" },
    { x: 490, l1: "Reset", l2: "" },
    { x: 630, l1: "Mirror", l2: "Heat" },
    { x: 770, l1: "Digital", l2: "Mirror" },
  ];
  const barY = 118, barH = 32, tsg = { x: 150, y: 250, w: 180, h: 356 };
  const fns = [
    { title: "Fold down exterior mirrors", drv: "H-bridge motor driver", out: "Unfolded / Folded" },
    { title: "Adjusting exterior mirrors", drv: "H-bridge motor driver", out: "Mirror movement · glass · fold" },
    { title: "Heating exterior mirrors", drv: "Electrical mirror heater", out: "Heating in progress" },
    { title: "Auto-dim exterior mirrors", drv: "Adjust voltage", out: "Dimmed exterior mirrors" },
    { title: "Auto-dim interior mirror", drv: "Detects glare", out: "Camera / digital mirror" },
  ];
  const fnX = 440, fnW = 400, fnH = 62, fnY0 = 268, fnGap = 74, actX = 878, actW = 190;
  const fy = (i) => fnY0 + i * fnGap;
  const AR = "url(#marAr)";
  return (
    <div style={{ border: "1px solid #E4E7EC", borderRadius: 8, background: "#F8FAFC", padding: 8, marginTop: 10, overflowX: "auto" }}>
      <div className="flex items-center justify-between flex-wrap" style={{ marginBottom: 6, gap: 8 }}>
        <div style={{ fontSize: 9.5, fontWeight: 700, color: "#98A2B3", letterSpacing: 0.3 }}>MIRROR SYSTEM ARCHITECTURE · CENTER ZONE MODULE</div>
        <div className="flex items-center gap-1.5" style={{ flexShrink: 0 }}>
          <button onClick={() => setZoom((z) => Math.max(0.3, +(z - 0.2).toFixed(2)))} title="Zoom out" style={zBtn}>−</button>
          <button onClick={() => setZoom((z) => Math.min(3, +(z + 0.2).toFixed(2)))} title="Zoom in" style={zBtn}>+</button>
          <button onClick={fit} title="Fit to page width" style={{ ...zBtn, width: 30 }}>⤢</button>
        </div>
      </div>
      <div ref={boxRef} style={{ overflow: "auto", border: "1px solid #EAECF0", borderRadius: 6, background: "#fff", maxHeight: 680 }}>
        <svg viewBox="0 0 1120 700" width={Math.round(1120 * zoom)} height={Math.round(700 * zoom)} style={{ display: "block", fontWeight: 700 }} xmlns="http://www.w3.org/2000/svg">
          <defs><marker id="marAr" markerWidth="8" markerHeight="8" refX="6" refY="3" orient="auto"><path d="M0,0 L6,3 L0,6 Z" fill="#5B7794" /></marker></defs>
          {/* Power + input buttons (Button / Touch) */}
          <text x={60} y={40} fontSize={9.5} fontWeight="700" fill="#98A2B3">Button / Touch</text>
          <g>
            <rect x={40} y={48} width={70} height={38} rx={5} fill="#FEF6EE" stroke="#F0C9A0" />
            <text x={75} y={72} fontSize={11} fontWeight="700" textAnchor="middle" fill="#B54708">12 V</text>
            <line x1={75} y1={86} x2={75} y2={barY} stroke="#B54708" strokeWidth={1.2} markerEnd={AR} />
          </g>
          {inputs.map((b, i) => (
            <g key={"in" + i}>
              <rect x={b.x - 55} y={48} width={110} height={38} rx={7} fill="#F2F4F7" stroke="#B6C0CC" />
              <text x={b.x} y={b.l2 ? 64 : 72} fontSize={10} fontWeight="700" textAnchor="middle" fill="#344054">{b.l1}</text>
              {b.l2 && <text x={b.x} y={78} fontSize={9} textAnchor="middle" fill="#667085">{b.l2}</text>}
              <line x1={b.x} y1={86} x2={b.x} y2={barY} stroke="#5B7794" strokeWidth={1.1} markerEnd={AR} />
            </g>
          ))}
          {/* Connected Center Zone bus bar */}
          <rect x={40} y={barY} width={1040} height={barH} rx={4} fill="#DCE9F7" stroke="#5B7794" />
          <text x={560} y={barY + 21} fontSize={12} fontWeight="700" textAnchor="middle" fill="#175CD3">Center Zone Module</text>
          {/* Center_Door_CAN01 → TSG door module */}
          <line x1={tsg.x + tsg.w / 2} y1={barY + barH} x2={tsg.x + tsg.w / 2} y2={tsg.y} stroke="#5B7794" strokeWidth={1.3} markerEnd={AR} />
          <text x={tsg.x + tsg.w / 2 + 8} y={(barY + barH + tsg.y) / 2} fontSize={8.5} fill="#98A2B3">Center_Door_CAN01</text>
          <rect x={tsg.x} y={tsg.y} width={tsg.w} height={tsg.h} rx={7} fill="#EAF2FF" stroke="#175CD3" strokeWidth={1.3} />
          <text x={tsg.x + tsg.w / 2} y={tsg.y + 24} fontSize={12} fontWeight="700" textAnchor="middle" fill="#175CD3">DCM-FL / DCM-FR</text>
          <text x={tsg.x + tsg.w / 2} y={tsg.y + 40} fontSize={8.5} textAnchor="middle" fill="#98A2B3">Door Control Modules (front doors)</text>
          {/* Mirrors subsystem container */}
          <rect x={fnX - 12} y={fnY0 - 34} width={fnW + 24} height={fns.length * fnGap + 22} rx={9} fill="#F8FAFC" stroke="#B6C0CC" />
          <text x={fnX} y={fnY0 - 16} fontSize={11} fontWeight="800" fill="#475467" letterSpacing={0.3}>MIRRORS</text>
          {fns.map((f, i) => {
            const y = fy(i), midY = y + fnH / 2;
            return (
              <g key={"fn" + i}>
                {/* TSG → function */}
                <line x1={tsg.x + tsg.w} y1={midY} x2={fnX} y2={midY} stroke="#5B7794" strokeWidth={1.1} markerEnd={AR} />
                {/* function block */}
                <rect x={fnX} y={y} width={fnW} height={fnH} rx={7} fill={f.hi ? "#EAF2FF" : "#fff"} stroke={f.hi ? "#175CD3" : "#B6C0CC"} strokeWidth={f.hi ? 1.6 : 1} />
                <text x={fnX + 14} y={y + 24} fontSize={11.5} fontWeight="700" fill={f.hi ? "#175CD3" : "#344054"}>{f.title}</text>
                <text x={fnX + 14} y={y + 44} fontSize={9.5} fill="#667085">{f.drv}</text>
                {/* function → actuator */}
                <line x1={fnX + fnW} y1={midY} x2={actX} y2={midY} stroke="#5B7794" strokeWidth={1.1} markerEnd={AR} />
                <rect x={actX} y={midY - 17} width={actW} height={34} rx={6} fill="#DCE5EF" stroke="#8FA8C4" />
                <text x={actX + actW / 2} y={midY + 4} fontSize={9} fontWeight="700" textAnchor="middle" fill="#1D2939">{f.out}</text>
              </g>
            );
          })}
          {/* Auto-dimming interior mirror (Y7.3, electrochromic) via Center_Roof_LIN01 → auto-dim interior mirror */}
          <rect x={tsg.x} y={630} width={tsg.w} height={48} rx={7} fill="#F2F4F7" stroke="#B6C0CC" />
          <text x={tsg.x + tsg.w / 2} y={649} fontSize={10} fontWeight="700" textAnchor="middle" fill="#344054">Auto-dimming interior mirror</text>
          <text x={tsg.x + tsg.w / 2} y={664} fontSize={8} textAnchor="middle" fill="#98A2B3">Y7.3 · electrochromic (EC)</text>
          <path d={`M${tsg.x + tsg.w},654 H400 V${fy(4) + fnH / 2} H${fnX}`} fill="none" stroke="#5B7794" strokeWidth={1.1} markerEnd={AR} />
          <text x={360} y={648} fontSize={8.5} fill="#98A2B3">Center_Roof_LIN01</text>
          {/* Rain / light weather input to interior auto-dim */}
          <rect x={actX} y={fy(4) + fnH + 8} width={actW} height={30} rx={6} fill="#FEF6EE" stroke="#F0C9A0" />
          <text x={actX + actW / 2} y={fy(4) + fnH + 27} fontSize={8.5} fontWeight="700" textAnchor="middle" fill="#B54708">Rain / light weather</text>
          <line x1={actX + actW / 2} y1={fy(4) + fnH + 8} x2={actX + actW / 2} y2={fy(4) + fnH / 2 + 17} stroke="#B54708" strokeWidth={1.1} markerEnd={AR} />
          <text x={60} y={fy(2)} fontSize={9} fill="#98A2B3">LIM_1</text>
        </svg>
      </div>
      <div style={{ fontSize: 8.5, color: "#98A2B3", marginTop: 6 }}>Redesigned from the platform mirror model — the Occupant Visibility mirror-function family. All functions share the Center Zone Module and the front Door Control Modules; each function (fold, adjust, heat, auto-dim) is its own L1 requirement.</div>
    </div>
  );
}
/* Complete Automotive SPICE (v3.1) Process Reference Model — all process groups (ACQ, SPL, SYS, SWE,
   SUP, MAN, REU, PIM) with the SYS+SWE V highlighted in the red assessment-scope box, and the three
   life-cycle categories (Primary / Organizational / Supporting) along the bottom. */
function AspiceFullProcess() {
  const [zoom, setZoom] = useState(1);
  const boxRef = useRef(null);
  const VW = 1280, VH = 748;
  const fit = () => { const el = boxRef.current; const w = el ? el.clientWidth - 6 : VW; setZoom(Math.max(0.3, Math.min(2.5, +(w / VW).toFixed(3)))); };
  useEffect(() => { const id = requestAnimationFrame(fit); const on = () => fit(); window.addEventListener("resize", on); return () => { cancelAnimationFrame(id); window.removeEventListener("resize", on); }; }, []);
  const zBtn = { fontSize: 12, fontWeight: 700, color: "#475467", border: "1px solid #E4E7EC", borderRadius: 5, width: 22, height: 20, background: "#fff", cursor: "pointer", lineHeight: 1 };
  const PINK = { body: "#FBEAE3", stroke: "#DCA593", code: "#7A2E17", name: "#8A4634", grpStroke: "#D98E76", grpTxt: "#7A2E17", foot: "#F7D9CE" };
  const BLUE = { body: "#E9EEF6", stroke: "#AEBFD6", code: "#243A5E", name: "#3A4E6E", grpStroke: "#9DB0C8", grpTxt: "#243A5E", foot: "#CFDAEA" };
  const GREEN = { body: "#E8F1E1", stroke: "#AACB9C", code: "#2E5122", name: "#3E6330", grpStroke: "#9CC488", grpTxt: "#2E5122", foot: "#D4E7C9" };
  const wrap = (s, n) => String(s).split(" ").reduce((a, w) => { const last = a[a.length - 1]; if (last && (last + " " + w).length <= n) a[a.length - 1] = last + " " + w; else a.push(w); return a; }, []);
  const P = (x, y, w, h, code, name, pal) => { const lines = wrap(name, Math.max(10, Math.floor(w / 5.4))); return (
    <g key={code}>
      <rect x={x} y={y} width={w} height={h} rx={3} fill={pal.body} stroke={pal.stroke} strokeWidth={1.2} />
      <text x={x + w / 2} y={y + 17} fontSize={11.5} fontWeight={800} textAnchor="middle" fill={pal.code}>{code}</text>
      {lines.map((ln, i) => <text key={i} x={x + w / 2} y={y + 31 + i * 10.5} fontSize={8.6} textAnchor="middle" fill={pal.name}>{ln}</text>)}
    </g>
  ); };
  const G = (x, y, w, h, title, pal) => { const lines = wrap(title, Math.max(8, Math.floor(w / 8.5))); return (
    <g>
      <rect x={x} y={y} width={w} height={h} rx={6} fill="none" stroke={pal.grpStroke} strokeWidth={1.4} />
      {lines.map((ln, i) => <text key={i} x={x + w / 2} y={y + 15 + i * 12} fontSize={10.5} fontWeight={800} textAnchor="middle" fill={pal.grpTxt}>{ln}</text>)}
    </g>
  ); };
  const label = (x, y, t, col) => <text x={x} y={y} fontSize={11.5} fontWeight={800} textAnchor="middle" fill={col}>{t}</text>;
  const foot = (x, y, w, t, pal) => (
    <g>
      <rect x={x} y={y} width={w} height={22} rx={4} fill={pal.foot} stroke={pal.grpStroke} strokeWidth={1.2} />
      <text x={x + w / 2} y={y + 15} fontSize={10.5} fontWeight={800} textAnchor="middle" fill={pal.grpTxt}>{t}</text>
    </g>
  );
  const ACQ = [["ACQ.3", "Contract Agreement"], ["ACQ.4", "Supplier Monitoring"], ["ACQ.11", "Technical Requirements"], ["ACQ.12", "Legal and Administrative Requirements"], ["ACQ.13", "Project Requirements"], ["ACQ.14", "Request for Proposals"], ["ACQ.15", "Supplier Qualification"]];
  const SUPT = [["SUP.1", "Quality Assurance"], ["SUP.2", "Verification"], ["SUP.4", "Joint Review"], ["SUP.7", "Documentation"]];
  const SUPB = [["SUP.8", "Configuration Management"], ["SUP.9", "Problem Resolution Management"], ["SUP.10", "Change Request Management"]];
  return (
    <div style={{ border: "1px solid #E4E7EC", borderRadius: 8, background: "#F8FAFC", padding: 8, marginTop: 10 }}>
      <div className="flex items-center justify-between flex-wrap" style={{ marginBottom: 6, gap: 8 }}>
        <div style={{ fontSize: 9.5, fontWeight: 700, color: "#98A2B3", letterSpacing: 0.3 }}>AUTOMOTIVE SPICE v3.1 · PROCESS REFERENCE MODEL</div>
        <div className="flex items-center gap-1.5" style={{ flexShrink: 0 }}>
          <button onClick={() => setZoom((z) => Math.max(0.3, +(z - 0.2).toFixed(2)))} title="Zoom out" style={zBtn}>&minus;</button>
          <button onClick={() => setZoom((z) => Math.min(2.5, +(z + 0.2).toFixed(2)))} title="Zoom in" style={zBtn}>+</button>
          <button onClick={fit} title="Fit to page width" style={{ ...zBtn, width: 30 }}>&#10530;</button>
        </div>
      </div>
      <div ref={boxRef} style={{ overflow: "auto", border: "1px solid #EAECF0", borderRadius: 6, background: "#fff", maxHeight: 760 }}>
        <svg viewBox={`0 0 ${VW} ${VH}`} width={Math.round(VW * zoom)} height={Math.round(VH * zoom)} style={{ display: "block" }} xmlns="http://www.w3.org/2000/svg">
          <rect width={VW} height={VH} fill="#fff" />
          {/* ---- Acquisition (ACQ) ---- */}
          {G(12, 14, 224, 476, "Acquisition Process Group (ACQ)", PINK)}
          {ACQ.map((it, i) => P(24, 62 + i * 60, 200, 52, it[0], it[1], PINK))}
          {/* ---- Supply (SPL) ---- */}
          {G(12, 548, 224, 150, "Supply Process Group (SPL)", PINK)}
          {P(24, 592, 200, 44, "SPL.1", "Supplier Tendering", PINK)}
          {P(24, 644, 200, 44, "SPL.2", "Product Release", PINK)}
          {/* ---- Red assessment-scope box (SYS + SWE V) ---- */}
          {label(636, 44, "System Engineering Process Group (SYS)", "#7A2E17")}
          {P(286, 80, 176, 52, "SYS.1", "Requirements Elicitation", PINK)}
          {P(316, 150, 200, 52, "SYS.2", "System Requirements Analysis", PINK)}
          {P(336, 214, 200, 52, "SYS.3", "System Architectural Design", PINK)}
          {P(770, 150, 200, 52, "SYS.5", "System Qualification Test", PINK)}
          {P(770, 214, 200, 52, "SYS.4", "System Integration and Integration Test", PINK)}
          <line x1={258} y1={300} x2={1014} y2={300} stroke="#C9938A" strokeWidth={1} />
          {label(636, 320, "Software Engineering Process Group (SWE)", "#7A2E17")}
          {P(336, 348, 200, 52, "SWE.1", "Software Requirements Analysis", PINK)}
          {P(356, 410, 200, 52, "SWE.2", "Software Architectural Design", PINK)}
          {P(376, 466, 224, 48, "SWE.3", "Software Detailed Design and Unit Construction", PINK)}
          {P(770, 348, 200, 52, "SWE.6", "Software Qualification Test", PINK)}
          {P(770, 410, 200, 52, "SWE.5", "Software Integration and Integration Test", PINK)}
          {P(610, 466, 200, 48, "SWE.4", "Software Unit Verification", PINK)}
          <polyline points="278,92 600,506 1002,92" fill="none" stroke="#E4231B" strokeWidth={5} strokeLinejoin="round" strokeLinecap="round" />
          <rect x={250} y={24} width={772} height={498} rx={4} fill="none" stroke="#E4231B" strokeWidth={3.5} />
          {/* ---- Supporting (SUP) ---- */}
          {G(290, 548, 560, 156, "Supporting Process Group (SUP)", GREEN)}
          {SUPT.map((it, i) => P(300 + i * 134, 580, 124, 48, it[0], it[1], GREEN))}
          {SUPB.map((it, i) => P(300 + i * 178, 636, 168, 48, it[0], it[1], GREEN))}
          {/* ---- Management (MAN) ---- */}
          {G(1036, 24, 224, 232, "Management Process Group (MAN)", BLUE)}
          {P(1048, 72, 200, 46, "MAN.3", "Project Management", BLUE)}
          {P(1048, 128, 200, 46, "MAN.5", "Risk Management", BLUE)}
          {P(1048, 184, 200, 46, "MAN.6", "Measurement", BLUE)}
          {/* ---- Reuse (REU) ---- */}
          {G(1036, 470, 224, 108, "Reuse Process Group (REU)", BLUE)}
          {P(1048, 516, 200, 50, "REU.2", "Reuse Program Management", BLUE)}
          {/* ---- Process Improvement (PIM) ---- */}
          {G(1036, 598, 224, 102, "Process Improvement Process Group (PIM)", BLUE)}
          {P(1048, 648, 200, 44, "PIM.3", "Process Improvement", BLUE)}
          {/* ---- Life-cycle category footers ---- */}
          {foot(12, 716, 470, "Primary Life Cycle Processes", PINK)}
          {foot(496, 716, 360, "Organizational Life Cycle Processes", BLUE)}
          {foot(868, 716, 392, "Supporting Life Cycle Processes", GREEN)}
        </svg>
      </div>
      <div style={{ fontSize: 8.5, color: "#98A2B3", marginTop: 6 }}>Automotive SPICE v3.1 process reference model. The red box is the VDA assessment scope — the System (SYS.1&ndash;SYS.5) and Software (SWE.1&ndash;SWE.6) V that this project models end-to-end. ACQ / SPL / SUP / MAN / REU / PIM are the surrounding acquisition, supply, supporting and organizational processes.</div>
    </div>
  );
}
/* ASPICE V-model reference — SYS / SWE / HWE processes: left arm (specification & design) descends to
   implementation, right arm (verification & test) ascends, with the horizontal verification links. */
function AspiceVModel() {
  const [zoom, setZoom] = useState(1);
  const boxRef = useRef(null);
  const fit = () => { const el = boxRef.current; const w = el ? el.clientWidth - 6 : 1180; setZoom(Math.max(0.3, Math.min(3, +(w / 1180).toFixed(3)))); };
  useEffect(() => { const id = requestAnimationFrame(fit); const on = () => fit(); window.addEventListener("resize", on); return () => { cancelAnimationFrame(id); window.removeEventListener("resize", on); }; }, []);
  const zBtn = { fontSize: 12, fontWeight: 700, color: "#475467", border: "1px solid #E4E7EC", borderRadius: 5, width: 22, height: 20, background: "#fff", cursor: "pointer", lineHeight: 1 };
  const C = { sys: { f: "#E0F2FE", s: "#0E7090" }, swe: { f: "#EFF4FF", s: "#175CD3" }, hwe: { f: "#FEF6EE", s: "#B54708" }, impl: { f: "#F2F4F7", s: "#667085" } };
  const W = 210;
  const boxes = {
    "SYS.2": { x: 60, y: 54, h: 40, g: "sys", n: "System Requirements Analysis" },
    "SYS.3": { x: 130, y: 122, h: 40, g: "sys", n: "System Architectural Design" },
    "SWE.1": { x: 200, y: 194, h: 32, g: "swe", n: "SW Requirements Analysis" },
    "HWE.1": { x: 200, y: 230, h: 32, g: "hwe", n: "HW Requirements Analysis" },
    "SWE.2": { x: 270, y: 304, h: 32, g: "swe", n: "SW Architectural Design" },
    "HWE.2": { x: 270, y: 340, h: 32, g: "hwe", n: "HW Design" },
    "SWE.3": { x: 340, y: 414, h: 40, g: "swe", n: "SW Detailed Design & Unit Construction" },
    "IMPL": { x: 485, y: 486, h: 42, g: "impl", n: "Coding / Build (implementation)" },
    "SWE.4": { x: 630, y: 414, h: 40, g: "swe", n: "SW Unit Verification" },
    "SWE.5": { x: 700, y: 304, h: 32, g: "swe", n: "SW Integration Verification" },
    "HWE.3": { x: 700, y: 340, h: 32, g: "hwe", n: "Verification vs HW Design" },
    "SWE.6": { x: 770, y: 194, h: 32, g: "swe", n: "SW Qualification Test" },
    "HWE.4": { x: 770, y: 230, h: 32, g: "hwe", n: "Verification vs HW Requirements" },
    "SYS.4": { x: 840, y: 122, h: 40, g: "sys", n: "System Integration Test" },
    "SYS.5": { x: 910, y: 54, h: 40, g: "sys", n: "System Qualification Test" },
  };
  const flows = [["SYS.2", "SYS.3"], ["SYS.3", "SWE.1"], ["SYS.3", "HWE.1"], ["SWE.1", "SWE.2"], ["HWE.1", "HWE.2"], ["SWE.2", "SWE.3"], ["SWE.3", "IMPL"], ["HWE.2", "IMPL"], ["IMPL", "SWE.4"], ["IMPL", "HWE.3"], ["SWE.4", "SWE.5"], ["HWE.3", "HWE.4"], ["SWE.5", "SWE.6"], ["SWE.6", "SYS.4"], ["HWE.4", "SYS.4"], ["SYS.4", "SYS.5"]];
  const verify = [["SYS.2", "SYS.5"], ["SYS.3", "SYS.4"], ["SWE.1", "SWE.6"], ["HWE.1", "HWE.4"], ["SWE.2", "SWE.5"], ["HWE.2", "HWE.3"], ["SWE.3", "SWE.4"]];
  const edge = (a, b) => { const A = boxes[a], B = boxes[b], ax = A.x + W / 2, bx = B.x + W / 2; return B.y > A.y ? [ax, A.y + A.h, bx, B.y] : [ax, A.y, bx, B.y + B.h]; };
  const box = (k) => { const b = boxes[k], c = C[b.g], two = b.h > 34; return (
    <g key={k}>
      <rect x={b.x} y={b.y} width={W} height={b.h} rx={7} fill={c.f} stroke={c.s} strokeWidth={1.3} />
      {two ? (
        <>
          <text x={b.x + 10} y={b.y + 17} fontSize={11.5} fontWeight={800} fill={c.s}>{k === "IMPL" ? "" : k}</text>
          <text x={b.x + 10} y={b.y + 32} fontSize={9} fontWeight={600} fill="#475467">{b.n}</text>
        </>
      ) : (
        <text x={b.x + 10} y={b.y + 20}><tspan fontSize={10.5} fontWeight={800} fill={c.s}>{k}</tspan><tspan fontSize={9} fontWeight={600} fill="#475467" dx="7">{b.n}</tspan></text>
      )}
    </g>
  ); };
  return (
    <div style={{ border: "1px solid #E4E7EC", borderRadius: 8, background: "#F8FAFC", padding: 8, margin: 16, overflowX: "auto" }}>
      <div className="flex items-center justify-between flex-wrap" style={{ marginBottom: 6, gap: 8 }}>
        <div style={{ fontSize: 11, fontWeight: 700, color: "#98A2B3", letterSpacing: 0.3 }}>ASPICE V-MODEL · SYS.2–SYS.5 · SWE.1–SWE.6 · HWE.1–HWE.4</div>
        <div className="flex items-center gap-3">
          <div className="flex items-center gap-3" style={{ fontSize: 10, fontWeight: 700 }}>
            <span style={{ color: "#0E7090" }}>■ System</span><span style={{ color: "#175CD3" }}>■ Software</span><span style={{ color: "#B54708" }}>■ Hardware</span>
          </div>
          <div className="flex items-center gap-1.5" style={{ flexShrink: 0 }}>
            <button onClick={() => setZoom((z) => Math.max(0.3, +(z - 0.2).toFixed(2)))} title="Zoom out" style={zBtn}>−</button>
            <button onClick={() => setZoom((z) => Math.min(3, +(z + 0.2).toFixed(2)))} title="Zoom in" style={zBtn}>+</button>
            <button onClick={fit} title="Fit to page width" style={{ ...zBtn, width: 30 }}>⤢</button>
          </div>
        </div>
      </div>
      <div ref={boxRef} style={{ overflow: "auto", border: "1px solid #EAECF0", borderRadius: 6, background: "#fff", maxHeight: 720 }}>
        <svg viewBox="0 0 1180 560" width={Math.round(1180 * zoom)} height={Math.round(560 * zoom)} style={{ display: "block", fontFamily: "inherit" }} xmlns="http://www.w3.org/2000/svg">
          <defs><marker id="avmAr" markerWidth="8" markerHeight="8" refX="6" refY="3" orient="auto"><path d="M0,0 L6,3 L0,6 Z" fill="#B6C0CC" /></marker></defs>
          {flows.map((f, i) => { const [x1, y1, x2, y2] = edge(f[0], f[1]); return <line key={"f" + i} x1={x1} y1={y1} x2={x2} y2={y2} stroke="#B6C0CC" strokeWidth={1.3} markerEnd="url(#avmAr)" />; })}
          {verify.map((v, i) => { const A = boxes[v[0]], B = boxes[v[1]]; const y = A.y + A.h / 2; return (
            <g key={"v" + i}>
              <line x1={A.x + W} y1={y} x2={B.x} y2={y} stroke="#CBD5E1" strokeWidth={1} strokeDasharray="4 3" />
              <text x={(A.x + W + B.x) / 2} y={y - 3} fontSize={7.5} fontWeight={600} textAnchor="middle" fill="#98A2B3">verifies</text>
            </g>
          ); })}
          {Object.keys(boxes).map(box)}
          <text x={boxes.IMPL.x + W / 2} y={boxes.IMPL.y + 17} fontSize={11} fontWeight={800} textAnchor="middle" fill="#344054">IMPLEMENTATION</text>
        </svg>
      </div>
      <div style={{ fontSize: 8.5, color: "#98A2B3", marginTop: 6 }}>Left arm = specification &amp; design (SYS.2 → SYS.3 → SWE.1–3 / HWE.1–2 → implementation). Right arm = verification &amp; test rising back up. Dashed links show each process&rsquo;s corresponding verification (SYS.2↔SYS.5, SYS.3↔SYS.4, SWE.1↔SWE.6, SWE.2↔SWE.5, SWE.3↔SWE.4, HWE.1↔HWE.4, HWE.2↔HWE.3).</div>
    </div>
  );
}
/* Fold-down functional model — the fold command/status chain: CCU → CZM → DCM_FL fold control → fold motor,
   with the passenger/rear DCMs coordinating. Clickable ECU blocks open the ECU requirements. Rendered under
   the Fold Down "System Architecture" (SYS.3) aspect. */
function FoldFuncDiagram({ onEcu }) {
  const [zoom, setZoom] = useState(1);
  const boxRef = useRef(null);
  const fit = () => { const el = boxRef.current; const w = el ? el.clientWidth - 6 : 1120; setZoom(Math.max(0.3, Math.min(3, +(w / 1120).toFixed(3)))); };
  useEffect(() => { const id = requestAnimationFrame(fit); const on = () => fit(); window.addEventListener("resize", on); return () => { cancelAnimationFrame(id); window.removeEventListener("resize", on); }; }, []);
  const zBtn = { fontSize: 12, fontWeight: 700, color: "#475467", border: "1px solid #E4E7EC", borderRadius: 5, width: 22, height: 20, background: "#fff", cursor: "pointer", lineHeight: 1 };
  const B = {
    CCU: { label: "CCU", ecu: "ECU-CCU", head: "#C7DBF0", x: 430, y: 40, w: 260, h: 26, fns: [] },
    CZM: { label: "CZM", ecu: "ECU-CZM", head: "#C7DBF0", x: 430, y: 96, w: 260, h: 54, fns: ["Check vehicle and ignition status"] },
    INPUT: { label: "Inputs", head: "#E7EDF3", x: 24, y: 250, w: 160, h: 74, fns: ["Fold switch", "HOLD / UNFOLD"] },
    DCM_FL: { label: "DCM_FL", ecu: "ECU-DCM-FL", head: "#C7DBF0", x: 230, y: 210, w: 182, h: 134, fns: ["Authenticate user", "Validate the input", "Check current fold state", "Command fold motor (ab/FoldOut)", "Log Errors (if any)"] },
    DCM_FR: { label: "DCM_FR", ecu: "ECU-DCM-FR", head: "#C7DBF0", x: 500, y: 224, w: 140, h: 66, fns: ["Folds the mirror"] },
    DCM_RL: { label: "DCM_RL", ecu: "ECU-DCM-RL", head: "#C7DBF0", x: 700, y: 224, w: 140, h: 66, fns: ["Checks the mirror"] },
    DCM_RR: { label: "DCM_RR", ecu: "ECU-DCM-RR", head: "#C7DBF0", x: 892, y: 224, w: 140, h: 66, fns: ["Checks the mirror"] },
    MOT_FL: { label: "Driver Mirror Fold Motor", head: "#DCE5EF", x: 230, y: 424, w: 182, h: 72, fns: ["Receives command", "Folds / unfolds the mirror"] },
    MOT_FR: { label: "Passenger Mirror Fold Motor", head: "#DCE5EF", x: 500, y: 424, w: 140, h: 72, fns: ["Receives command", "Folds per the input"] },
    MOT_RL: { label: "Rear-Left Mirror Motor", head: "#DCE5EF", x: 700, y: 424, w: 140, h: 72, fns: ["No mirror to fold"] },
    MOT_RR: { label: "Rear-Right Mirror Motor", head: "#DCE5EF", x: 892, y: 424, w: 140, h: 72, fns: ["No mirror to fold"] },
  };
  const cx = (b) => b.x + b.w / 2;
  const wrap = (str, max) => { const ws = String(str).split(" "); const ls = []; let c = ""; ws.forEach((w) => { if ((c ? c + " " + w : w).length <= max) c = c ? c + " " + w : w; else { if (c) ls.push(c); c = w; } }); if (c) ls.push(c); return ls; };
  const A = (x1, y1, x2, y2) => <line x1={x1} y1={y1} x2={x2} y2={y2} stroke="#5B7794" strokeWidth={1.1} markerEnd="url(#ffdAr)" />;
  const T = (x, y, t, a = "middle") => <text x={x} y={y} fontSize={7.5} fontWeight="600" fill="#1D2939" textAnchor={a}>{t}</text>;
  const box = (id) => { const b = B[id], clk = !!(b.ecu && onEcu); return (
    <g key={id} onClick={clk ? () => onEcu(b.ecu) : undefined} style={clk ? { cursor: "pointer" } : undefined}>
      {clk && <title>Open {b.label} ECU requirements ({b.ecu})</title>}
      <rect x={b.x} y={b.y} width={b.w} height={b.h} rx={4} fill={clk ? "#F5FAFF" : "#fff"} stroke={clk ? "#175CD3" : "#5B7794"} />
      <path d={`M${b.x + 4},${b.y} h${b.w - 8} a4,4 0 0 1 4,4 v14 h${-b.w} v-14 a4,4 0 0 1 4,-4 z`} fill={b.head} />
      <text x={cx(b)} y={b.y + 13} fontSize={9.5} fontWeight="700" textAnchor="middle" fill={clk ? "#175CD3" : "#1D2939"} style={clk ? { textDecoration: "underline" } : undefined}>{b.label}</text>
      {(() => { const maxCh = Math.max(10, Math.floor((b.w - 12) / 4.3)); const dl = (b.fns || []).flatMap((fn) => wrap(fn, maxCh)); return dl.map((ln, i) => <text key={i} x={cx(b)} y={b.y + 30 + i * 11} fontSize={8} textAnchor="middle" fill="#475467">{ln}</text>); })()}
      <text x={b.x + b.w - 4} y={b.y + b.h - 4} fontSize={6} fontFamily="ui-monospace, monospace" textAnchor="end" fill="#AEB6C2">{b.ecu || (b.head === "#DCE5EF" ? "actuator" : "")}</text>
    </g>
  ); };
  return (
    <div style={{ border: "1px solid #E4E7EC", borderRadius: 8, background: "#F8FAFC", padding: 8, marginTop: 10, overflowX: "auto" }}>
      <div className="flex items-center justify-between flex-wrap" style={{ marginBottom: 6, gap: 8 }}>
        <div style={{ fontSize: 9.5, fontWeight: 700, color: "#98A2B3", letterSpacing: 0.3 }}>SYSTEM ARCHITECTURE (FUNCTIONAL MODEL) · FOLD DOWN EXTERIOR MIRRORS</div>
        <div className="flex items-center gap-1.5" style={{ flexShrink: 0 }}>
          <button onClick={() => setZoom((z) => Math.max(0.3, +(z - 0.2).toFixed(2)))} title="Zoom out" style={zBtn}>−</button>
          <button onClick={() => setZoom((z) => Math.min(3, +(z + 0.2).toFixed(2)))} title="Zoom in" style={zBtn}>+</button>
          <button onClick={fit} title="Fit to page width" style={{ ...zBtn, width: 30 }}>⤢</button>
        </div>
      </div>
      <div ref={boxRef} style={{ overflow: "auto", border: "1px solid #EAECF0", borderRadius: 6, background: "#fff", maxHeight: 640 }}>
        <svg viewBox="0 0 1120 540" width={Math.round(1120 * zoom)} height={Math.round(540 * zoom)} style={{ display: "block" }} xmlns="http://www.w3.org/2000/svg">
          <defs><marker id="ffdAr" markerWidth="8" markerHeight="8" refX="6" refY="3" orient="auto"><path d="M0,0 L6,3 L0,6 Z" fill="#5B7794" /></marker></defs>
          {/* CCU -> CZM trigger */}
          {A(cx(B.CCU), B.CCU.y + B.CCU.h, cx(B.CZM), B.CZM.y)}
          {T(cx(B.CCU) + 96, (B.CCU.y + B.CCU.h + B.CZM.y) / 2 + 2, "Center_Platform_CAN01 · Enable / wake", "start")}
          {/* CZM -> DCM bus */}
          {A(cx(B.CZM), B.CZM.y + B.CZM.h, cx(B.CZM), 190)}
          <line x1={cx(B.DCM_FL)} y1={190} x2={cx(B.DCM_RR)} y2={190} stroke="#5B7794" />
          {T((cx(B.DCM_FL) + cx(B.DCM_RR)) / 2, 184, "Center_Door_CAN01 · SP_FoldIn / SP_FoldOut · SSA_FT/BFT_ASP_Fold_Status / _Fault · FT_SP_Unlatched")}
          {["DCM_FL", "DCM_FR", "DCM_RL", "DCM_RR"].map((k) => <line key={k} x1={cx(B[k])} y1={190} x2={cx(B[k])} y2={B[k].y} stroke="#5B7794" markerEnd="url(#ffdAr)" />)}
          {/* Inputs -> DCM_FL */}
          {A(B.INPUT.x + B.INPUT.w, B.INPUT.y + 20, B.DCM_FL.x, B.INPUT.y + 20)}
          {T((B.INPUT.x + B.INPUT.w + B.DCM_FL.x) / 2, B.INPUT.y + 14, "Fold / Unfold Request")}
          {/* DCM -> motor (Cmd/Resp) */}
          {["FL", "FR", "RL", "RR"].map((s) => { const d = B["DCM_" + s], m = B["MOT_" + s], x = cx(d); return (
            <g key={s}>
              {A(x - 8, d.y + d.h, x - 8, m.y)}{A(x + 8, m.y, x + 8, d.y + d.h)}
              {T(x - 12, (d.y + d.h + m.y) / 2, "Cmd", "end")}{T(x + 12, (d.y + d.h + m.y) / 2, "Resp", "start")}
            </g>
          ); })}
          {Object.keys(B).map(box)}
        </svg>
      </div>
      <div style={{ fontSize: 8.5, color: "#98A2B3", marginTop: 6 }}>Fold command/status over Center_Door_CAN01: SP_FoldIn / SP_FoldOut (fold in/out), SSA_FT/BFT_ASP_Fold_Status &amp; _Fault (status/fault), FT_SP_Unlatched (unlatched). ECU blocks are clickable — open the DCM/CZM/CCU requirements.</div>
    </div>
  );
}
