const L3_SETS = { [MIRROR_L3.parent]: MIRROR_L3, [FOLD_L3.parent]: FOLD_L3, [HEAT_L3.parent]: HEAT_L3, [DIM_L3.parent]: DIM_L3, [ADIM_L3.parent]: ADIM_L3, [WIPE_FR_L3.parent]: WIPE_FR_L3, [WASH_FR_L3.parent]: WASH_FR_L3, [WIPE_RR_L3.parent]: WIPE_RR_L3, [WASH_RR_L3.parent]: WASH_RR_L3, [WLEVEL_L3.parent]: WLEVEL_L3, [WSHORT_L3.parent]: WSHORT_L3, [NOZZLEHEAT_L3.parent]: NOZZLEHEAT_L3, [WIPESVC_L3.parent]: WIPESVC_L3 };

/* Promote the L3/L4 worked example to real nodes + decomposes_to edges (L2 aspect -> L3 -> L4) when the
   parent L1 is generated, so they appear in the Table, Graph and SYSTEMS tree with full traceability. */
function genMirrorL3L4(l1) {
  const out = { nodes: [], edges: [] };
  const SET = L3_SETS[l1.id];
  if (!SET) return out;
  const base = l1.id.replace(/^L1-/, "");
  const common = { parentL0: l1.props?.parentL0, domain: l1.props?.domain, subdomain: l1.props?.subdomain };
  const addL3 = (r, kind) => {
    const isAr = kind === "AR", disc = isAr ? "SW" : kind;
    const subL3 = isAr ? "L3 SW architecture" : `L3 ${kind} requirement`, lvlL3 = isAr ? "L3 (SW architecture, SWE.2)" : `L3 (${kind} requirement)`;
    const subL4 = isAr ? "L4 SW design" : (kind === "HW" ? "L4 HW design" : `L4 ${kind} requirement`), lvlL4 = isAr ? "L4 (SW detailed design, SWE.3)" : (kind === "HW" ? "L4 (HW detailed design, HWE.2)" : `L4 (${kind} detailed requirement)`);
    out.nodes.push({ id: r.id, type: "Requirement", label: r.title, subtype: subL3, ...GEN,
      props: P({ statement: r.statement, level: lvlL3, discipline: disc, allocation: r.alloc, tracesFrom: (r.from || []).map((a) => `L2-${base}-${a}`).join(", "), ...common, status: "Proposed — pending review" }) });
    (r.from || []).forEach((a) => out.edges.push({ s: `L2-${base}-${a}`, t: r.id, e: "decomposes_to" }));
    (r.l4 || []).forEach((x) => {
      out.nodes.push({ id: x.id, type: "Requirement", label: x.title, subtype: subL4, ...GEN,
        props: P({ statement: x.statement, level: lvlL4, discipline: disc, parentL3: r.id, ...common, status: "Proposed" }) });
      out.edges.push({ s: r.id, t: x.id, e: "decomposes_to" });
    });
  };
  SET.sw.forEach((r) => addL3(r, "SW"));
  (SET.arch || []).forEach((r) => addL3(r, "AR"));
  SET.hw.forEach((r) => addL3(r, "HW"));
  return out;
}
function MirrorL3Panel({ l1Prefix = "1.1", l2n = 6 }) {
  const D = MIRROR_L3;
  const [open, setOpen] = useState(() => new Set([...D.sw, ...(D.arch || []), ...D.hw].filter((r) => r.l4 && r.l4.length).map((r) => r.id))); // L4 expanded by default
  const numOf = (() => { const all = [...D.sw, ...(D.arch || []), ...D.hw], map = {}; all.forEach((r, k) => { const n3 = l1Prefix + "." + (l2n + k + 1); map[r.id] = n3; (r.l4 || []).forEach((x, m) => (map[x.id] = n3 + "." + (m + 1))); }); return map; })();
  const disc = { SW: { c: "#175CD3", bg: "#EFF4FF" }, AR: { c: "#7A5AF8", bg: "#F4F1FE" }, HW: { c: "#B54708", bg: "#FEF6EE" } };
  const asp = ASPECT_NAMES;
  const section = (title, sub, items, kind) => (
    <div style={{ marginTop: 8 }}>
      <div style={{ fontSize: 10, fontWeight: 700, color: disc[kind].c }}>{title} <span style={{ color: "#98A2B3", fontWeight: 400 }}>· {sub}</span></div>
      {items.map((r) => { const isOpen = open.has(r.id); return (
        <div key={r.id} style={{ border: "1px solid #EAECF0", borderRadius: 6, background: "#fff", marginTop: 5, overflow: "hidden" }}>
          <div className="flex items-start gap-2 px-2.5 py-1.5">
            <span style={{ fontSize: 8.5, fontWeight: 700, color: disc[kind].c, background: disc[kind].bg, borderRadius: 4, padding: "1px 5px", flexShrink: 0, marginTop: 1 }}>{kind}</span>
            <div className="flex-1 min-w-0">
              <div className="flex items-center gap-2 flex-wrap">
                <span style={{ fontSize: 11, fontWeight: 700, color: "#175CD3", fontFamily: "ui-monospace, monospace" }}>{numOf[r.id]}</span>
                <span style={{ fontSize: 11.5, fontWeight: 600, color: "#101828" }}>{r.title}</span>
                <span style={{ fontSize: 8.5, color: "#B6C0CC", fontFamily: "ui-monospace, monospace" }}>{r.id}</span>
              </div>
              <p style={{ fontSize: 11, color: "#667085", marginTop: 2, lineHeight: 1.5 }}>{r.statement}</p>
              <div className="flex flex-wrap items-center gap-2 mt-1" style={{ fontSize: 8.5, color: "#98A2B3" }}>
                <span>traces: {r.from.map((a) => asp[a] || a).join(", ")}</span>
                <span>· alloc: {r.alloc}</span>
                {r.l4 && r.l4.length > 0 && <button onClick={() => setOpen((p) => { const s = new Set(p); s.has(r.id) ? s.delete(r.id) : s.add(r.id); return s; })} style={{ color: "#175CD3", fontWeight: 600 }}>{isOpen ? "▾ hide L4" : "▸ L4 (" + r.l4.length + ")"}</button>}
              </div>
            </div>
          </div>
          {isOpen && r.l4 && r.l4.length > 0 && (
            <div style={{ borderTop: "1px solid #F2F4F7", background: "#FBFCFD", padding: "5px 10px 6px 36px" }}>
              <div style={{ fontSize: 8, fontWeight: 700, color: "#98A2B3", letterSpacing: 0.3, marginBottom: 2 }}>L4 · {kind === "SW" ? "detailed software requirements" : kind === "AR" ? "software detailed design (SWE.3)" : "detailed hardware requirements"}</div>
              {r.l4.map((x) => (
                <div key={x.id} style={{ marginTop: 3 }}>
                  <div className="flex items-center gap-2"><span style={{ fontSize: 10, fontWeight: 700, color: "#175CD3", fontFamily: "ui-monospace, monospace" }}>{numOf[x.id]}</span><span style={{ fontSize: 10.5, fontWeight: 600, color: "#344054" }}>{x.title}</span><span style={{ fontSize: 8, color: "#B6C0CC", fontFamily: "ui-monospace, monospace" }}>{x.id}</span></div>
                  <p style={{ fontSize: 10, color: "#98A2B3", lineHeight: 1.45 }}>{x.statement}</p>
                </div>
              ))}
            </div>
          )}
        </div>
      ); })}
    </div>
  );
  return (
    <div style={{ border: "1px solid #E4E7EC", borderRadius: 8, background: "#F8FAFC", padding: 10, marginTop: 12 }}>
      <div style={{ fontSize: 10, fontWeight: 700, color: "#98A2B3", letterSpacing: 0.4 }}>L3 — DERIVED HW / SW REQUIREMENTS <span style={{ fontWeight: 400 }}>· traced from the L2 aspects · rolls down to L4 (worked example)</span></div>
      {section("Software requirements", "SWE.1 · allocated to DCM software", D.sw, "SW")}
      {D.arch && D.arch.length > 0 && section("Software architecture", "SWE.2 · allocated to DCM software", D.arch, "AR")}
      {section("Hardware requirements", "HWE.1 · allocated to DCM hardware", D.hw, "HW")}
    </div>
  );
}
const L3_PANELS = { "L1-BODY-00187": MirrorL3Panel };

/* ===== SECTION: UI pieces ===== */
function TypeChip({ t, small }) {
  const m = meta(t);
  return (
    <span className="inline-flex items-center gap-1" style={{ color: m.c }}>
      <span style={{ width: 6, height: 6, borderRadius: 2, background: m.c, display: "inline-block" }} />
      <span style={{ fontSize: small ? 9.5 : 10.5, fontWeight: 700, letterSpacing: 0.3 }}>{m.n}</span>
    </span>
  );
}

/* Graph node card: type chip, label, key facts, and the expand/add/copy/delete
   affordances. onSelect fires on click (records nav history via App's effect). */
function NodeCard({ node, x, y, selected, isFocus, hidden, onSelect, onExpand, onAdd, onCopy, onDelete, canWrite }) {
  const m = meta(node.type);
  const ActionBtn = ({ dx, fill, stroke, glyph, title, onClick }) => (
    <g transform={`translate(${dx},-34)`} style={{ cursor: "pointer" }}
      onClick={(ev) => { ev.stopPropagation(); onClick(); }}>
      <title>{title}</title>
      <rect x={0} y={0} width={24} height={24} rx={6} fill={fill} stroke={stroke} strokeWidth={1} />
      {glyph}
    </g>
  );
  return (
    <g transform={`translate(${x},${y})`} style={{ cursor: "pointer" }}>
      <rect x={0} y={-19} width={m.n.length * 6.4 + 8} height={14} rx={3}
        fill="#FBFCFD" opacity={0.92} />
      <text x={4} y={-8} fontSize={10} fontWeight={700} fill={m.c}
        fontFamily="ui-monospace, SFMono-Regular, Menlo, monospace">
        {m.n.toUpperCase()}
      </text>
      <rect width={NW} height={NH} rx={7} fill="#fff"
        stroke={selected ? m.c : isFocus ? BRAND.ink : "#E4E7EC"}
        strokeWidth={selected || isFocus ? 2 : 1} onClick={() => onSelect(node.id)} />
      <rect width={3.5} height={NH} rx={2} fill={m.c} onClick={() => onSelect(node.id)} />
      {(node.edited || node.isNew) && (
        <circle cx={NW - 12} cy={12} r={4} fill={node.isNew ? "#7F56D9" : "#B54708"}>
          <title>{node.isNew ? "New node" : "Edited"}</title>
        </circle>
      )}
      <text x={14} y={24} fontSize={12} fontWeight={600} fill="#101828" onClick={() => onSelect(node.id)}>
        {(node.label || "").slice(0, 26)}{(node.label || "").length > 26 ? "…" : ""}
      </text>
      <text x={14} y={43} fontSize={10} fill="#667085"
        fontFamily="ui-monospace, SFMono-Regular, Menlo, monospace" onClick={() => onSelect(node.id)}>
        {node.id}
      </text>
      {node.subtype && (
        <text x={14} y={55} fontSize={9} fill="#98A2B3" onClick={() => onSelect(node.id)}>
          {node.subtype.slice(0, 30)}
        </text>
      )}
      {hidden > 0 && (
        <g onClick={(ev) => { ev.stopPropagation(); onExpand(node.id); }}>
          <rect x={NW - 30} y={NH / 2 - 12} width={24} height={24} rx={6} fill="#F2F4F7" stroke="#E4E7EC" />
          <text x={NW - 18} y={NH / 2 + 4} fontSize={10} fontWeight={700} fill="#475467" textAnchor="middle">
            {hidden}
          </text>
        </g>
      )}
      {selected && canWrite && (
        <>
          <ActionBtn dx={NW - 78} fill="#EAF2FF" stroke="#B2CCFF" title="Add child node" onClick={() => onAdd(node.id)}
            glyph={<><line x1={12} y1={7} x2={12} y2={17} stroke="#175CD3" strokeWidth={2} /><line x1={7} y1={12} x2={17} y2={12} stroke="#175CD3" strokeWidth={2} /></>} />
          <ActionBtn dx={NW - 50} fill="#F6F1FE" stroke="#D9C7FB" title="Copy this box" onClick={() => onCopy(node.id)}
            glyph={<><rect x={9} y={9} width={8} height={8} rx={1.5} fill="none" stroke="#7F56D9" strokeWidth={1.6} /><rect x={6.5} y={6.5} width={8} height={8} rx={1.5} fill="#F6F1FE" stroke="#7F56D9" strokeWidth={1.6} /></>} />
          <ActionBtn dx={NW - 22} fill="#FEF3F2" stroke="#FDA29B" title="Delete this box" onClick={() => onDelete(node.id)}
            glyph={<><line x1={8} y1={9} x2={16} y2={9} stroke="#B42318" strokeWidth={1.6} /><line x1={10} y1={9} x2={10.5} y2={16} stroke="#B42318" strokeWidth={1.6} /><line x1={14} y1={9} x2={13.5} y2={16} stroke="#B42318" strokeWidth={1.6} /><line x1={10} y1={7.5} x2={14} y2={7.5} stroke="#B42318" strokeWidth={1.6} /></>} />
        </>
      )}
    </g>
  );
}

/* ===== SECTION: App component ===== */
/* ==========================================================================
   INTERCHANGE EXPORTS — ARXML (AUTOSAR system description) and ODX (ISO 22901
   diagnostics). Both are SCOPED, well-formed DRAFTS generated from the tool's
   live data:
     - ARXML: the six ECU instances, the communication clusters implied by the
       loaded buses (CAN / Ethernet / LIN / FlexRay), the normalized interfaces
       as I-SIGNALs, and a SYSTEM that references them via FIBEX-ELEMENTS.
     - ODX:  one ECU-VARIANT per ECU with a UDS service skeleton (0x19 / 0x22)
       and DTCs derived from that ECU's FMEA failure modes.
   These follow the AUTOSAR / ODX element structure but are NOT guaranteed to be
   schema-valid against a particular AUTOSAR release or ODX version — element
   sets and versions must be aligned with the target toolchain before import.
   ========================================================================== */
const xmlEsc = (s) => String(s == null ? "" : s).replace(/&/g, "&amp;").replace(/</g, "&lt;").replace(/>/g, "&gt;").replace(/"/g, "&quot;");
const arName = (s) => String(s || "X").replace(/[^A-Za-z0-9_]/g, "_").replace(/^([0-9])/, "_$1").slice(0, 120);

/* All loaded ECU interfaces, tagged with their owning ECU. */
const ALL_ECU_IO = () => [
  ...CCU_IO.map((x) => ({ ...x, ecu: "ECU-CCU" })),
  ...CCM_IO.map((x) => ({ ...x, ecu: "ECU-CCM" })),
  ...CZM_IO.map((x) => ({ ...x, ecu: "ECU-CZM" })),
  ...FZM_IO.map((x) => ({ ...x, ecu: "ECU-FZM" })),
  ...ADAS_IO.map((x) => ({ ...x, ecu: "ECU-ADAS" })),
  ...RRDCU_IO.map((x) => ({ ...x, ecu: "ECU-RRDCU" })),
  ...SRCU_IO.map((x) => ({ ...x, ecu: "ECU-SRCU" })),
  ...PSCU_IO.map((x) => ({ ...x, ecu: "ECU-PSCU" })),
  ...PDUF_IO.map((x) => ({ ...x, ecu: "ECU-PDUF" })),
  ...PDUR_IO.map((x) => ({ ...x, ecu: "ECU-PDUR" })),
  ...OUTD_IO.map((x) => ({ ...x, ecu: "ECU-OUTD" })),
  ...APHB_IO.map((x) => ({ ...x, ecu: "ECU-APHB" })),
];

/* I/O category from interface class (or an explicit kind for LIN/CAN mechatronic devices). */
const ioCategory = (cls, kind) => {
  if (kind) return kind;
  const c = (cls || "").toUpperCase();
  if (/BUS-|NET-ETH|A2B/.test(c)) return "Network/Bus";
  if (/RF-/.test(c)) return "Wireless/RF";
  if (/CAM/.test(c)) return "Camera/Sensor";
  if (/SEN-|MIC/.test(c)) return "Sensor";
  if (/DISP/.test(c)) return "Display/Output";
  if (/MOT|AUD-ANLG/.test(c)) return "Actuator";
  if (/PWR/.test(c)) return "Power";
  if (/GND/.test(c)) return "Ground";
  if (/USB/.test(c)) return "USB/Data";
  if (/DIO|CTL/.test(c)) return "Discrete I/O";
  if (/DIAG/.test(c)) return "Diagnostic";
  return "Other";
};
/* Complete ECU I/O for the harness TABLE export: the connector pin-out arrays PLUS the display side
   (BST/CID/FID), the loop-generated KESSY antennas and AUX outlets, and the LIN/CAN mechatronic
   sensor/actuator device lists. Superset of ALL_ECU_IO (which stays connector-only for KBL/VEC/ARXML). */
const FULL_ECU_IO = () => {
  const out = ALL_ECU_IO().map((x) => ({ ...x }));
  BST_IO.forEach((x) => out.push({ ...x, ecu: "ECU-BST" }));
  CID_IO.forEach((x) => out.push({ ...x, ecu: "ECU-CID" }));
  FID_IO.forEach((x) => out.push({ ...x, ecu: "ECU-FID" }));
  NETWORK.ecus.filter((e) => e.rsadConn).forEach((e) => {
    out.push({ ecu: e.id, id: e.id.replace("ECU-", "") + "-IF-001", conn: e.rsadConn, name: "UWB(+BLE) antenna (KESSY / anti-theft)", cls: "BUS-CAN", proto: "CAN FD", dir: "Bidir", pins: 6, endpoint: "CZM Center Vehicle-Access CAN01", ecuIf: e.rsadConn + " · A1..A6 CAN FD + coding + T30" });
  });
  [["ECU-OUTA", "U11.3"], ["ECU-OUTB", "U17.3"], ["ECU-OUTC", "U30.3"]].forEach(([eid, conn]) => {
    [["V2L LIN control", "BUS-LIN", "LIN", "Bidir", 2, "CZM Body LIN (V2L socket control)"],
     ["Power supply (KL30 / KL31)", "PWR", "KL30 / KL31", "In", 2, "Vehicle power net (V.30_AUX / GND)"],
     ["230V/110V AC output", "PWR", "230V/110V AC", "Out", 4, "V2L AC socket (L1 / N / PE)"]].forEach((r, i) => {
      out.push({ ecu: eid, id: eid.replace("ECU-", "") + "-IF-" + String(i + 1).padStart(3, "0"), conn, name: r[0], cls: r[1], proto: r[2], dir: r[3], pins: r[4], endpoint: r[5], ecuIf: conn });
    });
  });
  (NETWORK.io || []).forEach((io) => {
    [["LIN", io.lin], ["CAN", io.can]].forEach(([bus, devs]) => (devs || []).forEach((dev, i) => {
      const kind = /sensor|sensing|feedback|switch|level|angle|current|voltage|temperature/i.test(dev) ? "Sensor" : "Actuator";
      out.push({ ecu: io.host, id: "SA-" + io.host + "-" + bus + "-" + (i + 1), conn: "(" + bus + " bus)", name: dev, cls: bus === "LIN" ? "BUS-LIN" : "BUS-CAN", proto: bus, dir: "Bidir", pins: "", endpoint: dev, ecuIf: io.serves || "", _kind: kind });
    }));
  });
  return out;
};

/* Map an interface protocol/class to an AUTOSAR communication-cluster family.
   Sensor / power / discrete lines are not communication clusters -> null. */
const clusterFamily = (proto, cls) => {
  const p = `${proto || ""} ${cls || ""}`.toUpperCase();
  if (/FLEX/.test(p)) return "FlexRay";
  if (/ETH|BASE-T|A2B/.test(p)) return "Ethernet";
  if (/\bLIN\b/.test(p)) return "Lin";
  if (/CAN/.test(p)) return "Can";
  return null;
};

/* ===== SECTION: Export — ARXML (AUTOSAR) ===== */
function buildARXML() {
  const io = ALL_ECU_IO();
  const ecus = NETWORK.ecus;
  const fam = { Can: [], Ethernet: [], Lin: [], FlexRay: [] };
  io.forEach((x) => { const f = clusterFamily(x.proto, x.cls); if (f && fam[f]) fam[f].push(x); });
  const clusterEl = { Can: "CAN-CLUSTER", Ethernet: "ETHERNET-CLUSTER", Lin: "LIN-CLUSTER", FlexRay: "FLEXRAY-CLUSTER" };
  const chEl = { Can: "CAN-PHYSICAL-CHANNEL", Ethernet: "ETHERNET-PHYSICAL-CHANNEL", Lin: "LIN-PHYSICAL-CHANNEL", FlexRay: "FLEXRAY-PHYSICAL-CHANNEL" };
  const L = [];
  L.push('<?xml version="1.0" encoding="UTF-8"?>');
  L.push('<!-- SDVsolution EKG Explorer — scoped AUTOSAR system-description draft. Align element set/version with the target AUTOSAR release before import. -->');
  L.push('<AUTOSAR xmlns="http://autosar.org/schema/r4.0" xmlns:xsi="http://www.w3.org/2001/XMLSchema-instance" xsi:schemaLocation="http://autosar.org/schema/r4.0 AUTOSAR_00050.xsd">');
  L.push('  <AR-PACKAGES><AR-PACKAGE><SHORT-NAME>SDVsolution</SHORT-NAME><AR-PACKAGES>');

  /* ECU instances */
  L.push('    <AR-PACKAGE><SHORT-NAME>EcuInstances</SHORT-NAME><ELEMENTS>');
  ecus.forEach((e) => {
    L.push('      <ECU-INSTANCE><SHORT-NAME>' + arName(e.id.replace("ECU-", "")) + '</SHORT-NAME>');
    L.push('        <DESC><L-2 L="EN">' + xmlEsc(`${e.name} — ${e.vendor} ${e.processor}, ASIL ${e.asil}`) + '</L-2></DESC>');
    L.push('      </ECU-INSTANCE>');
  });
  L.push('    </ELEMENTS></AR-PACKAGE>');

  /* Communication clusters (one per protocol family present) */
  L.push('    <AR-PACKAGE><SHORT-NAME>Communication</SHORT-NAME><ELEMENTS>');
  Object.keys(fam).forEach((f) => {
    if (!fam[f].length) return;
    const U = f.toUpperCase();
    L.push('      <' + clusterEl[f] + '><SHORT-NAME>' + f + '_Cluster</SHORT-NAME>');
    L.push('        <' + U + '-CLUSTER-VARIANTS><' + U + '-CLUSTER-CONDITIONAL>');
    L.push('          <PHYSICAL-CHANNELS><' + chEl[f] + '><SHORT-NAME>' + f + '_Channel</SHORT-NAME></' + chEl[f] + '></PHYSICAL-CHANNELS>');
    L.push('        </' + U + '-CLUSTER-CONDITIONAL></' + U + '-CLUSTER-VARIANTS>');
    L.push('      </' + clusterEl[f] + '>');
  });
  L.push('    </ELEMENTS></AR-PACKAGE>');

  /* Interfaces as I-SIGNALs */
  L.push('    <AR-PACKAGE><SHORT-NAME>Signals</SHORT-NAME><ELEMENTS>');
  io.forEach((x) => {
    if (!clusterFamily(x.proto, x.cls)) return;
    L.push('      <I-SIGNAL><SHORT-NAME>' + arName(x.ecu.replace("ECU-", "") + "_" + x.id) + '</SHORT-NAME>');
    L.push('        <DESC><L-2 L="EN">' + xmlEsc(`${x.name} · ${x.proto} · ${x.dir} · endpoint ${x.endpoint}`) + '</L-2></DESC>');
    L.push('        <LENGTH>8</LENGTH></I-SIGNAL>');
  });
  L.push('    </ELEMENTS></AR-PACKAGE>');

  /* System referencing the ECUs and clusters via FIBEX */
  L.push('    <AR-PACKAGE><SHORT-NAME>System</SHORT-NAME><ELEMENTS>');
  L.push('      <SYSTEM><SHORT-NAME>SDV_System</SHORT-NAME><FIBEX-ELEMENTS>');
  ecus.forEach((e) => L.push('        <FIBEX-ELEMENT-REF-CONDITIONAL><FIBEX-ELEMENT-REF DEST="ECU-INSTANCE">/SDVsolution/EcuInstances/' + arName(e.id.replace("ECU-", "")) + '</FIBEX-ELEMENT-REF></FIBEX-ELEMENT-REF-CONDITIONAL>'));
  Object.keys(fam).forEach((f) => { if (fam[f].length) L.push('        <FIBEX-ELEMENT-REF-CONDITIONAL><FIBEX-ELEMENT-REF DEST="' + clusterEl[f] + '">/SDVsolution/Communication/' + f + '_Cluster</FIBEX-ELEMENT-REF></FIBEX-ELEMENT-REF-CONDITIONAL>'); });
  L.push('      </FIBEX-ELEMENTS></SYSTEM>');
  L.push('    </ELEMENTS></AR-PACKAGE>');

  L.push('  </AR-PACKAGES></AR-PACKAGE></AR-PACKAGES>');
  L.push('</AUTOSAR>');
  return L.join("\n");
}

/* ===== SECTION: Export — ODX (ISO 22901) ===== */
function buildODX() {
  const ecus = NETWORK.ecus;
  const L1 = GRAPH.nodes.filter((n) => n.type === "Requirement" && /L1/.test(n.subtype || ""));
  const L = [];
  L.push('<?xml version="1.0" encoding="UTF-8"?>');
  L.push('<!-- SDVsolution EKG Explorer — scoped ODX (ISO 22901) diagnostics draft. DTCs derived from FMEA failure modes; align with the target ODX version before import. -->');
  L.push('<ODX MODEL-VERSION="2.2.0" xmlns:xsi="http://www.w3.org/2001/XMLSchema-instance" xsi:noNamespaceSchemaLocation="odx.xsd">');
  L.push('  <DIAG-LAYER-CONTAINER ID="DLC_SDV"><SHORT-NAME>SDV_Diagnostics</SHORT-NAME>');
  L.push('    <ECU-VARIANTS>');
  ecus.forEach((e, ei) => {
    const code = arName(e.id.replace("ECU-", ""));
    const mine = L1.filter((n) => ecuFor(n) === e.id);
    let dtcs = [];
    mine.forEach((n) => { try { const g = genFMEA(n); (g.nodes || []).forEach((fn) => { if (fn.type === "FMEAItem") dtcs.push(fn); }); } catch (x) {} });
    const capped = dtcs.slice(0, 40);
    L.push('      <ECU-VARIANT ID="EV_' + code + '"><SHORT-NAME>' + code + '</SHORT-NAME>');
    L.push('        <LONG-NAME>' + xmlEsc(e.name) + '</LONG-NAME>');
    L.push('        <DESC><L-2 L="EN">' + xmlEsc(`${e.vendor} ${e.processor}, ASIL ${e.asil} · ${dtcs.length} candidate DTC(s) from FMEA` + (dtcs.length > 40 ? " (first 40 shown)" : "")) + '</L-2></DESC>');
    L.push('        <DIAG-DATA-DICTIONARY-SPEC><DTC-DOPS><DTC-DOP ID="DTCDOP_' + code + '"><SHORT-NAME>DTCs_' + code + '</SHORT-NAME><DTCS>');
    capped.forEach((fn, i) => {
      const tc = ((ei + 1) * 0x1000 + i).toString(16).toUpperCase().padStart(6, "0");
      L.push('          <DTC ID="DTC_' + code + '_' + i + '"><SHORT-NAME>DTC_' + code + '_' + i + '</SHORT-NAME>');
      L.push('            <TROUBLE-CODE>0x' + tc + '</TROUBLE-CODE>');
      L.push('            <TEXT>' + xmlEsc((fn.label || "Failure mode") + " — " + (fn.props && fn.props.effect || "")) + '</TEXT>');
      L.push('            <DISPLAY-TROUBLE-CODE>' + xmlEsc("P" + tc.slice(-4)) + '</DISPLAY-TROUBLE-CODE></DTC>');
    });
    L.push('        </DTCS></DTC-DOP></DTC-DOPS></DIAG-DATA-DICTIONARY-SPEC>');
    L.push('        <DIAG-COMMS>');
    L.push('          <DIAG-SERVICE ID="SVC_RDTC_' + code + '" SEMANTIC="FAULTREAD"><SHORT-NAME>ReadDTCInformation</SHORT-NAME><LONG-NAME>UDS 0x19</LONG-NAME></DIAG-SERVICE>');
    L.push('          <DIAG-SERVICE ID="SVC_RDBI_' + code + '" SEMANTIC="DATA"><SHORT-NAME>ReadDataByIdentifier</SHORT-NAME><LONG-NAME>UDS 0x22</LONG-NAME></DIAG-SERVICE>');
    L.push('        </DIAG-COMMS>');
    L.push('      </ECU-VARIANT>');
  });
  L.push('    </ECU-VARIANTS>');
  L.push('  </DIAG-LAYER-CONTAINER>');
  L.push('</ODX>');
  return L.join("\n");
}

/* ==========================================================================
   HARNESS-EXCHANGE EXPORTS — KBL (VDA) and VEC (prostep iViP), the formats
   Siemens Capital ingests from the OEM's logical system concept. Both are
   SCOPED, well-formed DRAFTS built from the Logicals connectivity:
     - connector housings (one per ECU connector) with cavities (pins),
     - nets/connections (one per interface) between the ECU connector and its
       endpoint, carrying the signal/protocol.
   They carry the OEM-owned LOGICAL layer only (no wire gauge, terminals, seals,
   lengths or 3D routing — that is the supplier's physical mastering). Align to
   your OEM KBL/VEC profile and the supplier's Capital import config before use.
   ========================================================================== */
const _ioByConnector = () => {
  const map = {};
  ALL_ECU_IO().forEach((x) => { const k = x.ecu + "|" + x.conn; (map[k] = map[k] || { ecu: x.ecu, conn: x.conn, items: [] }).items.push(x); });
  return map;
};

/* ===== SECTION: Export — KBL (VDA Kabelbaumliste) ===== */
function buildKBL() {
  const io = ALL_ECU_IO();
  const byConn = _ioByConnector();
  const L = [];
  L.push('<?xml version="1.0" encoding="UTF-8"?>');
  L.push('<!-- SDVsolution EKG Explorer \u2014 scoped KBL (VDA) logical-connectivity draft for Siemens Capital / the harness supplier. Logical layer only. Align to your OEM KBL profile and the supplier import config before use. -->');
  L.push('<KBL_CONTAINER xmlns="http://www.prostep.org/kbl" VERSION="2.5">');
  L.push('  <HARNESS>');
  L.push('    <ID>SDV_LOGICAL_HARNESS</ID>');
  L.push('    <ABBREVIATION>SDV-LOG</ABBREVIATION>');
  L.push('    <DESCRIPTION>SDVsolution logical electrical connectivity (as-wired from ECU pin-outs)</DESCRIPTION>');
  /* connector housings — one per ECU connector, cavities = interfaces */
  Object.values(byConn).forEach((g) => {
    const enm = ECU_BY_ID[g.ecu]?.name || g.ecu, code = g.ecu.replace("ECU-", "");
    L.push('    <CONNECTOR_HOUSING>');
    L.push('      <ID>' + arName(code + "_" + g.conn) + '</ID>');
    L.push('      <PART_NUMBER>' + arName(code) + '-CONN-' + arName(g.conn) + '</PART_NUMBER>');
    L.push('      <DESCRIPTION>' + xmlEsc(enm + " \u2014 connector " + g.conn) + '</DESCRIPTION>');
    g.items.forEach((x, i) => {
      L.push('      <SLOT><ID>' + arName(x.id) + '_S</ID>');
      L.push('        <CAVITY><ID>' + arName(x.id) + '_C</ID><CAVITY_NUMBER>' + (i + 1) + '</CAVITY_NUMBER><DESCRIPTION>' + xmlEsc(x.name + " (" + x.cls + ", " + x.pins + " pin)") + '</DESCRIPTION></CAVITY>');
      L.push('      </SLOT>');
    });
    L.push('    </CONNECTOR_HOUSING>');
  });
  /* connections — each interface is a logical net between the ECU connector and its endpoint */
  io.forEach((x) => {
    const code = x.ecu.replace("ECU-", "");
    L.push('    <CONNECTION>');
    L.push('      <ID>' + arName(x.id) + '</ID>');
    L.push('      <SIGNAL_NAME>' + xmlEsc(x.name) + '</SIGNAL_NAME>');
    L.push('      <DESCRIPTION>' + xmlEsc(x.cls + " \u00b7 " + x.proto + " \u00b7 " + x.dir) + '</DESCRIPTION>');
    L.push('      <WIRE_NUMBER>' + arName(x.id) + '</WIRE_NUMBER>');
    L.push('      <EXTREMITY><CONTACT_POINT>' + arName(code + "_" + x.conn) + '</CONTACT_POINT><CAVITY_REF>' + arName(x.id) + '_C</CAVITY_REF></EXTREMITY>');
    L.push('      <EXTREMITY><CONTACT_POINT>' + xmlEsc(x.endpoint) + '</CONTACT_POINT></EXTREMITY>');
    L.push('    </CONNECTION>');
  });
  L.push('  </HARNESS>');
  L.push('</KBL_CONTAINER>');
  return L.join("\n");
}

/* ===== SECTION: Export — VEC (prostep iViP) ===== */
function buildVEC() {
  const io = ALL_ECU_IO();
  const ecus = NETWORK.ecus;
  const L = [];
  L.push('<?xml version="1.0" encoding="UTF-8"?>');
  L.push('<!-- SDVsolution EKG Explorer \u2014 scoped VEC (prostep iViP) logical-connectivity draft for Siemens Capital. Logical layer only. Align to the target VEC version and supplier profile before use. -->');
  L.push('<vec:VecContent xmlns:vec="http://www.prostep.org/ecad" xmlns:xsi="http://www.w3.org/2001/XMLSchema-instance" vecVersion="2.1.0">');
  /* components — one per ECU */
  ecus.forEach((e) => {
    L.push('  <vec:Component>');
    L.push('    <vec:Identification>' + arName(e.id.replace("ECU-", "")) + '</vec:Identification>');
    L.push('    <vec:ComponentType>ECU</vec:ComponentType>');
    L.push('    <vec:Description>' + xmlEsc(e.name + " \u2014 " + e.vendor + " " + e.processor + ", ASIL " + e.asil) + '</vec:Description>');
    L.push('  </vec:Component>');
  });
  /* network specification — each interface is a net between the ECU connector and its endpoint */
  L.push('  <vec:NetworkSpecification>');
  L.push('    <vec:Identification>SDV_LOGICAL</vec:Identification>');
  io.forEach((x) => {
    L.push('    <vec:Net>');
    L.push('      <vec:Identification>' + arName(x.id) + '</vec:Identification>');
    L.push('      <vec:NetName>' + xmlEsc(x.name) + '</vec:NetName>');
    L.push('      <vec:NetType>' + xmlEsc(x.cls) + '</vec:NetType>');
    L.push('      <vec:SignalName>' + xmlEsc(x.proto) + '</vec:SignalName>');
    L.push('      <vec:NetNode><vec:ComponentRef>' + arName(x.ecu.replace("ECU-", "")) + '</vec:ComponentRef><vec:Connector>' + xmlEsc(x.conn) + '</vec:Connector><vec:Direction>' + xmlEsc(x.dir) + '</vec:Direction></vec:NetNode>');
    L.push('      <vec:NetNode><vec:EndpointRef>' + xmlEsc(x.endpoint) + '</vec:EndpointRef></vec:NetNode>');
    L.push('    </vec:Net>');
  });
  L.push('  </vec:NetworkSpecification>');
  L.push('</vec:VecContent>');
  return L.join("\n");
}

/* ==========================================================================
   App — the single root component. Holds all UI state:
     focus/selected      the node in view and the one shown in the detail panel
     nav {hist, idx}      back/forward navigation history over selections
     expanded             which nodes are unfolded in the graph
     view                 active view: table | tree(Graph) | reader | deploy
                          (Topology) | logicals
     nodes/edges          live overrides layered on the generated GRAPH
     feedback/creating/...    modals and inline editors
   Then: derived helpers, handlers, and the five view renderers + detail panel.
   ========================================================================== */
/* ECU requirements specification template — 12 standard chapters, content derived from the ECU record
   where known and template "shall" requirements otherwise. Used by the ECU Requirements page. */
function ecuReqChapters(ecu) {
  const tag = ecu.smart ? ecu.id : ecuTag(ecu.id), name = ecu.name, asil = ecu.asil || "QM", sup = ecu.supplier || "TBD";
  const ven = ecu.vendor && ecu.vendor !== "—" ? ecu.vendor : "TBD", proc = ecu.processor && ecu.processor !== "—" ? ecu.processor : "TBD";
  const codes = (ecu.codes || []).join(", ") || "—", primary = isPrimaryEcu(ecu.id);
  return [
    { n: "General Information", intro: `${name} (${tag} · ${ecu.id}) — ${ecu.deviceClass}. Scope: ${ecu.scope}. Supplier: ${sup}; silicon vendor: ${ven}; processor: ${proc}; safety integrity: ASIL ${asil}. Feature/software domains: ${codes}.`, reqs: [
      `The ${tag} shall be uniquely identifiable by part number, hardware revision and software version, and shall report all three over UDS diagnostics.`,
      `The ${tag} shall fulfil the role of "${ecu.deviceClass}" within the vehicle E/E architecture and meet ASIL ${asil} where safety goals are allocated to it.`,
      `The ${tag} shall be classified as a ${primary ? "primary (compute/zonal) ECU hosting application software" : "secondary/peripheral ECU"} on the vehicle network.` ] },
    { n: "Electrical Architecture", intro: `Connector, pin-out and signal-level electrical characteristics for ${tag}.`, reqs: [
      `The ${tag} shall implement the connector cavities, pin assignment and wire gauges defined in its connector/pin-out ICD.`,
      `All ${tag} inputs and outputs shall meet the specified voltage levels, current ratings, and short-to-battery / short-to-ground protection.`,
      `The ${tag} shall meet the applicable ESD, over-voltage, reverse-polarity and load-dump robustness levels (ISO 7637 / ISO 16750).` ] },
    { n: "Network Topology", intro: `Bus connectivity and communication role of ${tag}${codes !== "—" ? " (domains: " + codes + ")" : ""}.`, reqs: [
      `The ${tag} shall connect to the specified CAN-FD / LIN / Ethernet buses and implement the frames and signals allocated to it in the K-Matrix (communication matrix).`,
      `The ${tag} shall support the network-management (NM) strategy, bus sleep/wake, and partial-networking behaviour defined for its buses.`,
      `The ${tag} shall meet the timing, cycle-time and end-to-end (E2E) protection requirements for its safety-relevant signals.` ] },
    { n: "Hardware Requirements", intro: `Compute, memory, I/O and peripheral hardware resources for ${tag}.`, reqs: [
      `The ${tag} hardware shall provide the microcontroller/SoC throughput, RAM/flash, timers, and I/O resources to meet its functional and timing requirements with defined reserve.`,
      `The ${tag} shall provide the driver stages, sensing and interface circuitry required by its allocated functions.`,
      asil !== "QM" ? `The ${tag} hardware shall implement the safety mechanisms (lockstep, monitoring, watchdog, secure element) required for ASIL ${asil}.` : `The ${tag} hardware shall implement watchdog and supply monitoring appropriate to a QM component.` ] },
    { n: "Software Requirements", intro: `Application, basic-software and platform software for ${tag}.`, reqs: [
      `The ${tag} software shall implement the functions allocated to it (${codes}) per the software requirements and be built on the specified AUTOSAR / platform stack.`,
      `The ${tag} software shall support UDS diagnostics (DTC handling, routines, I/O control) and software update (flash bootloader, A/B or OTA as specified).`,
      `The ${tag} software shall enforce SecOC / secure boot and access control as required by the cybersecurity concept.` ] },
    { n: "Environmental Conditions", intro: `Operating and storage environment for ${tag}.`, reqs: [
      `The ${tag} shall operate across its specified ambient temperature range and survive the storage-temperature and thermal-cycling profiles for its mounting location.`,
      `The ${tag} shall meet the required ingress-protection (IP) rating and resistance to humidity, salt-mist, dust and fluids for its installation zone.`,
      `The ${tag} shall meet the mechanical vibration and shock profiles defined for its mounting location.` ] },
    { n: "Mechanical Integration", intro: `Packaging, mounting and connector mechanics for ${tag}.`, reqs: [
      `The ${tag} shall conform to the defined housing envelope, mass, mounting-interface and fixing points.`,
      `The ${tag} connectors shall be keyed, sealed and rated per the mating and retention requirements for the installation zone.`,
      `The ${tag} shall meet the thermal-dissipation and heat-sinking requirements for its packaging.` ] },
    { n: "Power Supply Requirements", intro: `Supply architecture and consumption for ${tag}.`, reqs: [
      `The ${tag} shall operate from its specified supply rails (e.g. KL30 / KL15 / switched) across the defined voltage range including cranking and start-stop transients.`,
      `The ${tag} shall meet its quiescent (sleep) and active current-consumption budgets and support the low-power / wake strategy for its buses.`,
      `The ${tag} shall protect against over-voltage, under-voltage, reverse polarity and load-dump on all supply inputs.` ] },
    { n: "Failure and Degradation Concepts", intro: `Fault handling, safe states and degraded modes for ${tag}.`, reqs: [
      `The ${tag} shall detect, react to and log faults (self-test, plausibility, supply, communication, actuator) and enter the defined safe state on unrecoverable faults.`,
      `The ${tag} shall provide the specified degraded/limp-home behaviour and driver notification when partial functionality is lost.`,
      asil !== "QM" ? `The ${tag} shall meet the fault-tolerant-time-interval (FTTI) and diagnostic-coverage targets of its ASIL ${asil} safety goals.` : `The ${tag} shall log faults as DTCs with freeze-frame data for service.` ] },
    { n: "Calibration Requirements", intro: `Calibratable parameters and their management for ${tag}.`, reqs: [
      `The ${tag} shall expose its calibratable parameters (thresholds, maps, variant coding) via the defined calibration/measurement interface (e.g. XCP).`,
      `The ${tag} shall support variant coding / end-of-line parameterisation and store calibration data in protected, versioned non-volatile memory.`,
      `The ${tag} shall validate calibration data integrity at start-up and fall back to safe defaults on corruption.` ] },
    { n: "Manufacturing and Service Requirements", intro: `Production, end-of-line and field-service needs for ${tag}.`, reqs: [
      `The ${tag} shall support end-of-line programming, configuration, and test (flashing, coding, actuator test) within the defined cycle time.`,
      `The ${tag} shall support field service operations: re-flash, re-coding, component replacement and guided diagnostics.`,
      `The ${tag} shall provide traceability data (serial number, production date, supplier code) readable over diagnostics.` ] },
    { n: "Regulatory and Compliance Requirements", intro: `Type-approval, EMC and homologation obligations for ${tag}.`, reqs: [
      `The ${tag} shall comply with the applicable EMC directives/regulations (e.g. UN R10, CISPR 25, ISO 11452) for emissions and immunity.`,
      `The ${tag} shall comply with functional-safety (ISO 26262) and cybersecurity (ISO/SAE 21434, UN R155/R156) process and product requirements as applicable.`,
      `The ${tag} shall comply with the regional homologation, environmental (RoHS/REACH) and radio (where a transmitter is present) requirements for the target markets.` ] },
  ];
}

