  "L2-BODY-00194-ARCH": [{"stage":"SYS.4","method":"System integration (HIL)","title":"SWC communication","pre":"Software components deployed per the architecture.","stim":"Exercise the sender/receiver and client/server ports realising Heating Exterior Mirrors.","exp":"Signals/operations are exchanged with the specified ports, IDs and timing; allocation matches the K‑Matrix/ARXML."},{"stage":"SYS.4","method":"System integration (HIL)","title":"Allocation & interfaces","pre":"Architecture elements allocated to ECUs.","stim":"Verify each element hosting Heating Exterior Mirrors against its allocation.","exp":"Every element is allocated to the correct ECU with its interfaces defined; no unallocated element."}],
  "L2-BODY-00197-FUN": [{"stage":"SYS.5","method":"System qualification (vehicle)","title":"Nominal Provide Wash Water Level","pre":"KL15 ON; no active DTC; system in a state that permits Provide Wash Water Level.","stim":"Trigger Provide Wash Water Level under nominal conditions and hold for the specified duration.","exp":"The function performs its specified behaviour; outputs settle within tolerance and the specified time; no DTC."},{"stage":"SYS.5","method":"System qualification (vehicle)","title":"Boundary of operating range","pre":"System at a defined min/max operating limit for Provide Wash Water Level.","stim":"Exercise Provide Wash Water Level at the lower and upper bounds of its operating range.","exp":"Behaviour stays within limits; correct clamping at the end‑stops/limits; no overrun or oscillation."},{"stage":"SYS.5","method":"System qualification (vehicle)","title":"Fault reaction","pre":"A component, feedback or supply fault can be injected.","stim":"Inject a fault while Provide Wash Water Level is active.","exp":"The function enters its defined safe/degraded state, sets the corresponding DTC and drives no unsafe output."}],
  "L2-BODY-00197-IF": [{"stage":"SYS.4","method":"System integration (HIL)","title":"Input → command mapping","pre":"Bus/IO trace active for Provide Wash Water Level.","stim":"Assert each defined input (signal/discrete) individually.","exp":"Each input maps to the correct internal command/parameter with the specified range, unit and update rate."},{"stage":"SYS.4","method":"System integration (HIL)","title":"Timeout & safe default","pre":"An input signal is normally received.","stim":"Suppress the input beyond its specified timeout.","exp":"The signal substitutes its defined safe (default) value; a communication/timeout DTC is set; output held safe."},{"stage":"SYS.4","method":"System integration (HIL)","title":"Range / plausibility","pre":"Interface exchanging analogue or counted values.","stim":"Drive an out‑of‑range / implausible value on the interface.","exp":"Value is rejected or clamped per spec; no propagation of the invalid value; plausibility DTC where defined."}],
  "L2-BODY-00197-PERF": [{"stage":"SYS.5","method":"System qualification (bench)","title":"End‑to‑end latency","pre":"Instrumented input and resulting output for Provide Wash Water Level.","stim":"Actuate the input and timestamp the resulting output over 20 repetitions.","exp":"End‑to‑end latency ≤ the specified budget across all repetitions (worst case recorded)."},{"stage":"SYS.5","method":"System qualification (bench)","title":"Cadence & jitter","pre":"Trace the controlling runnable/frame cadence.","stim":"Run Provide Wash Water Level for 60 s under nominal load.","exp":"Cadence equals the specified period with jitter inside budget; no missed cycles."}],
  "L2-BODY-00197-MODE": [{"stage":"SYS.5","method":"System qualification (vehicle)","title":"Mode entry / exit","pre":"System able to transition through the defined modes.","stim":"Command entry into, then exit from, each operating mode of Provide Wash Water Level.","exp":"Transitions occur only when the guard conditions are met; state is reported correctly at each step."},{"stage":"SYS.5","method":"System qualification (vehicle)","title":"Reject outside allowed window","pre":"Vehicle in a mode where Provide Wash Water Level is not permitted.","stim":"Request Provide Wash Water Level.","exp":"Request is rejected; no output; mode/state unchanged."},{"stage":"SYS.5","method":"System qualification (vehicle)","title":"Fault → safe state","pre":"Function active in a normal mode.","stim":"Inject a fault that forces a mode change.","exp":"Function transitions to the defined safe state within the specified time and latches until cleared."}],
  "L2-BODY-00197-DIAG": [{"stage":"SYS.4","method":"System integration (HIL)","title":"DTC set on fault","pre":"Diagnostic tester connected (UDS).","stim":"Inject the monitored fault condition and let the debounce elapse.","exp":"The specified DTC is set to confirmed with a freeze‑frame; status bits reflect the fault."},{"stage":"SYS.4","method":"System integration (HIL)","title":"Heal / clear","pre":"A previously confirmed DTC is present.","stim":"Remove the fault and run the required healing cycles, then issue ClearDTC.","exp":"DTC transitions to passed/healed then cleared; freeze‑frame cleared; no residual fault."},{"stage":"SYS.4","method":"System integration (HIL)","title":"No false detection","pre":"No fault present; nominal operation.","stim":"Run Provide Wash Water Level through its normal range for an extended period.","exp":"No DTC is falsely set; monitors remain in the passed state."}],
  "L2-BODY-00197-SAF": [{"stage":"SYS.4","method":"Safety validation (HIL)","title":"Safe state within FTTI","pre":"Safety mechanism enabled for Provide Wash Water Level.","stim":"Inject the hazardous fault the safety goal addresses.","exp":"The system reaches the defined safe state within the fault‑tolerant time interval, consistent with the allocated ASIL."},{"stage":"SYS.4","method":"Safety validation (HIL)","title":"Independent monitoring","pre":"Primary control path and monitor both active.","stim":"Force the primary path to produce an incorrect output.","exp":"The independent monitor detects the deviation and commands the safe state; no single‑point failure defeats it."}],
  "L2-BODY-00197-SEC": [{"stage":"SYS.4","method":"Security test (HIL)","title":"Authenticated request accepted","pre":"SecOC / UDS security active.","stim":"Send a correctly authenticated command to Provide Wash Water Level.","exp":"Command is accepted and executed; freshness/MAC verified."},{"stage":"SYS.4","method":"Security test (HIL)","title":"Reject tampered / unauthorised","pre":"Security mechanism active.","stim":"Send a malformed, replayed or unauthenticated request.","exp":"Request is rejected and logged; no state change; attempt‑limit / delay applied where defined."}],
  "L2-BODY-00197-BND": [{"stage":"SYS.4","method":"System integration (HIL)","title":"Boundary inputs cross correctly","pre":"System boundary instrumented for Provide Wash Water Level.","stim":"Drive each external input that crosses the system boundary.","exp":"Each crossing input is received with correct scaling/units and routed to the right internal element."},{"stage":"SYS.4","method":"System integration (HIL)","title":"Boundary outputs & diagnostics","pre":"Actuators / neighbouring systems observable.","stim":"Command each boundary output and query diagnostics.","exp":"Outputs and diagnostic responses at the boundary match the interface specification."}],
  "L2-BODY-00197-ARCH": [{"stage":"SYS.4","method":"System integration (HIL)","title":"SWC communication","pre":"Software components deployed per the architecture.","stim":"Exercise the sender/receiver and client/server ports realising Provide Wash Water Level.","exp":"Signals/operations are exchanged with the specified ports, IDs and timing; allocation matches the K‑Matrix/ARXML."},{"stage":"SYS.4","method":"System integration (HIL)","title":"Allocation & interfaces","pre":"Architecture elements allocated to ECUs.","stim":"Verify each element hosting Provide Wash Water Level against its allocation.","exp":"Every element is allocated to the correct ECU with its interfaces defined; no unallocated element."}],
