  "L3-BODY-00187-SW-02": [{"stage":"SWE.4","method":"Software unit test","title":"Nominal — Timing & scheduling","pre":"Unit under test isolated; nominal inputs.","stim":"Call Timing & scheduling with representative in‑range inputs.","exp":"Output equals the expected value; post‑conditions hold; full MC/DC on the decision logic."},{"stage":"SWE.4","method":"Software unit test","title":"Boundary — Timing & scheduling","pre":"Unit isolated.","stim":"Apply min, max and just‑outside‑range inputs.","exp":"Values clamped/handled per spec; no overflow; correct saturation behaviour."},{"stage":"SWE.4","method":"Software unit test","title":"Fault path — Timing & scheduling","pre":"Unit isolated; error injection possible.","stim":"Inject invalid input / dependency failure.","exp":"Unit returns the defined error/default and sets the fault flag; no undefined behaviour."}],
