  "L3-BODY-00187-HW-01": [{"stage":"HWE.3","method":"Hardware verification (bench)","title":"Nominal — Mirror-motor driver output","pre":"ECU on bench; nominal supply and load.","stim":"Exercise Mirror-motor driver output for Adjusting Exterior Mirrors under nominal conditions.","exp":"Measured behaviour meets the hardware requirement within tolerance."},{"stage":"HWE.3","method":"Hardware verification (bench)","title":"Electrical limit — Mirror-motor driver output","pre":"Supply/temperature at the spec limits.","stim":"Apply the min/max supply, load and temperature.","exp":"Parameter stays within the specified range; protection engages at the defined thresholds."},{"stage":"HWE.4","method":"Hardware verification vs requirements","title":"Fault — open‑load / short","pre":"Fault injection harness fitted.","stim":"Inject open‑load and short‑to‑GND/BATT on the driven output.","exp":"Driver detects the fault, limits current and reports it; no damage; DTC set."}],
