      reviewTotal: reviewIds.length, reviewApproved: approvedN, reviewInReview: stCounts["In Review"], reviewBaselined: stCounts["Baselined"], statusCounts: stCounts,
      approvedPct: reviewIds.length ? Math.round(100 * approvedN / reviewIds.length) : 0,
