  const importBaselineFile = (file) => { if (!file) return; const r = new FileReader(); r.onload = () => { try { const obj = JSON.parse(r.result); const list = Array.isArray(obj) ? obj : [obj]; const norm = list.filter((b) => b && b.snap).map((b) => ({ id: b.id || ("BL-" + Date.now() + "-" + Math.random().toString(36).slice(2, 6)), name: b.name || "Imported baseline", ts: b.ts || new Date().toISOString(), snap: b.snap })); if (!norm.length) { setBlMsg("No baselines found in file"); return; } setBaselines((p) => [...norm, ...p]); setBlMsg("Imported " + norm.length + " baseline" + (norm.length === 1 ? "" : "s")); } catch (e) { setBlMsg("Import failed — invalid JSON"); } }; r.readAsText(file); };
