  const [ownerEdit, setOwnerEdit] = useState(null); // { id, value }
  const [supEdit, setSupEdit] = useState(null); // ECU supplier inline edit { id, value }
  const [dreEdit, setDreEdit] = useState(null); // { id, value } — Design Responsible Engineer inline edit
